/* WHO SAID IT? — GAME OF THRONES quote pool.
   { d: 1 easy | 3 hard, fmt: "show"|"book", q, speaker, wrong: [3 names], s?, b?, hint, context }
   speaker/wrong MUST be exact keys from PEOPLE_IMGS (js/people.js) so portraits resolve.
   s = safe once SEEN that season (show quotes only); b = safe once READ that book (book quotes only).
   Three rules this pool is held to, all learned by breaking them:
     1. A quote must NOT contain its own speaker's name or house — "I am no lady, I'm Brienne of
        Tarth" is not a question, it is an answer. Trim the line to an accurate excerpt if the rest
        still points at them by inference; otherwise cut it.
     2. No house words, oaths or ritual phrases ("Valar morghulis", "Words are wind", the Watch's
        funeral rite) — a formulaic line has more than one truthful speaker, so more than one option
        is correct.
     3. No two quotes may collide. Two near-identical lines by different speakers make both unfair.
   Accuracy first: re-verify wording before adding a quote, and soften the phrasing rather than
   assert a detail you are unsure of. */
window.QUOTES = window.QUOTES || {};
window.QUOTES.got = [

  // ================= SHOW — EASY =================
  { d: 1, fmt: "show", q: "You know nothing, Jon Snow.", speaker: "Ygritte", wrong: ["Osha", "Gilly", "Karsi"], s: 2, hint: "A wildling's favorite tease for a Night's Watch brother.", context: "Ygritte's running line to Jon, mocking how little he understands of the free folk's world." },
  { d: 1, fmt: "show", q: "I drink and I know things.", speaker: "Tyrion Lannister", wrong: ["Bronn", "Varys", "Jorah Mormont"], s: 5, hint: "A dwarf's blunt answer when asked what he's good for.", context: "Tyrion's self-summary, delivered somewhere between wine cups." },
  { d: 1, fmt: "show", q: "When you play the game of thrones, you win or you die.", speaker: "Cersei Lannister", wrong: ["Tywin Lannister", "Petyr Baelish", "Varys"], s: 1, hint: "Said by a queen to a Hand she doesn't trust.", context: "Cersei's warning to Ned Stark, laying out the rules of the court he's just entered." },
  { d: 1, fmt: "show", q: "The night is dark and full of terrors.", speaker: "Melisandre", wrong: ["Davos Seaworth", "Tywin Lannister", "Stannis Baratheon"], s: 2, hint: "A red priestess's prayer to her god of flame.", context: "Melisandre's ritual phrase, invoked whenever she calls on the Lord of Light." },
  { d: 1, fmt: "show", q: "Chaos is a ladder.", speaker: "Petyr Baelish", wrong: ["Varys", "Tywin Lannister", "Roose Bolton"], s: 3, hint: "A schemer explaining his own philosophy to a spymaster.", context: "Littlefinger's speech to Varys about ambition and the value of disorder." },
  { d: 1, fmt: "show", q: "Dracarys.", speaker: "Daenerys Targaryen", wrong: ["Missandei", "Jorah Mormont", "Daario Naharis"], s: 3, hint: "High Valyrian for a single, fiery command.", context: "The word Daenerys teaches her dragons to mean 'dragonfire' — and uses to free the Unsullied." },
  { d: 1, fmt: "show", q: "The things I do for love.", speaker: "Jaime Lannister", wrong: ["Cersei Lannister", "Robert Baratheon", "Renly Baratheon"], s: 1, hint: "Said with a shrug, right before a shove.", context: "Jaime's remark just before he pushes Bran Stark from the tower window." },
  { d: 1, fmt: "show", q: "A girl has no name.", speaker: "Arya Stark", wrong: ["The Waif", "Sansa Stark", "Brienne of Tarth"], s: 6, hint: "An answer given by a would-be assassin in training.", context: "Arya's recitation as an acolyte of the House of Black and White, trying to give up her identity." },
  { d: 1, fmt: "show", q: "Everyone is mine to torment.", speaker: "Ramsay Bolton", wrong: ["Roose Bolton", "Joffrey Baratheon", "Gregor Clegane"], s: 3, hint: "A bastard's cruel claim over his newest captive.", context: "Ramsay's chilling declaration to Theon Greyjoy, early in his captivity." },
  { d: 1, fmt: "show", q: "It's not easy being drunk all the time. If it were easy, everyone would do it.", speaker: "Tyrion Lannister", wrong: ["Bronn", "Robert Baratheon", "Jorah Mormont"], s: 1, hint: "Said by a man who treats wine as a full-time occupation.", context: "Tyrion's cheerful defense of his own drinking habits." },
  { d: 1, fmt: "show", q: "There is only one god, and his name is Death. And there is only one thing we say to Death: not today.", speaker: "Syrio Forel", wrong: ["Jaqen H'ghar", "Yoren of the Night's Watch", "Ilyn Payne"], s: 1, hint: "A 'water dancing' teacher's lesson about facing fear.", context: "The dancing master's parting words to Arya, before his own last stand in the throne room." },
  { d: 1, fmt: "show", q: "The man who passes the sentence should swing the sword.", speaker: "Eddard Stark", wrong: ["Robert Baratheon", "Robb Stark", "Barristan Selmy"], s: 1, hint: "A northern lord's rule about doing your own dirty work.", context: "Ned Stark explaining to Bran why he beheads deserters himself rather than delegating it." },
  { d: 1, fmt: "show", q: "Power resides where men believe it resides.", speaker: "Varys", wrong: ["Petyr Baelish", "Tywin Lannister", "Illyrio Mopatis"], s: 2, hint: "A eunuch's riddle about kings, priests, and gold.", context: "Varys's riddle to Tyrion about the true nature of power, before the Battle of the Blackwater." },
  { d: 1, fmt: "show", q: "I am not going to stop the wheel. I'm going to break the wheel.", speaker: "Daenerys Targaryen", wrong: ["Tyrion Lannister", "Missandei", "Varys"], s: 5, hint: "A queen's promise to end an old cycle of power for good.", context: "Daenerys's declaration to Tyrion about her ambitions beyond simply taking the throne." },
  { d: 1, fmt: "show", q: "Even the smallest man can cast a very large shadow.", speaker: "Tyrion Lannister", wrong: ["Varys", "Bronn", "Jaime Lannister"], s: 1, hint: "Advice given by a small man to a crippled boy.", context: "Tyrion's parting words of encouragement to Bran Stark, before Bran's fall changes everything." },
  { d: 1, fmt: "show", q: "A mind needs books like a sword needs a whetstone.", speaker: "Tyrion Lannister", wrong: ["Samwell Tarly", "Maester Luwin", "Varys"], s: 1, hint: "A bookish dwarf's advice to a bastard heading north.", context: "Tyrion's gift of wisdom — and a reading list — to Jon Snow on the road to the Wall." },
  { d: 1, fmt: "show", q: "Fire cannot kill a dragon.", speaker: "Daenerys Targaryen", wrong: ["Missandei", "Jorah Mormont", "Tyrion Lannister"], s: 6, hint: "A queen's calm reminder before walking into a burning building.", context: "Daenerys's words to the assembled khals, moments before she burns the temple of the dosh khaleen." },

  // ================= SHOW — EASY (batch 2) =================
  { d: 1, fmt: "show", q: "Oh, my sweet summer child. What do you know about fear? Fear is for the winter, when the snows fall a hundred feet deep.", speaker: "Old Nan", wrong: ["Catelyn Stark", "Osha", "Maester Luwin"], s: 1, hint: "An old woman spinning fireside tales for a young lord who wanted something truly scary.", context: "Old Nan's answer to Bran, who begged her for a frightening story, in the halls of Winterfell." },
  { d: 1, fmt: "show", q: "I was never so alive as when I was winning this throne, or so dead as now that I've won it.", speaker: "Robert Baratheon", wrong: ["Eddard Stark", "Renly Baratheon", "Jaime Lannister"], s: 1, hint: "A weary king, confessing to his oldest friend just how hollow the crown has felt.", context: "Robert's confession to Ned Stark in the Winterfell crypts, standing before the statue of the woman he never stopped loving." },
  { d: 1, fmt: "show", q: "The lion does not concern himself with the opinions of the sheep.", speaker: "Tywin Lannister", wrong: ["Jaime Lannister", "Cersei Lannister", "Kevan Lannister"], s: 1, hint: "A father lecturing his golden son about pride, duty, and what really matters.", context: "Tywin's rebuke to Jaime after his humiliating capture by the Starks." },
  { d: 1, fmt: "show", q: "We who presume to rule must sometimes do vile things for the good of the realm.", speaker: "Varys", wrong: ["Petyr Baelish", "Tywin Lannister", "Illyrio Mopatis"], s: 1, hint: "A eunuch spymaster, justifying the cost of choices made in the shadows.", context: "Varys's defense of hard, ugly decisions made in service of the realm, spoken early in the first season." },
  { d: 1, fmt: "show", q: "You have many admirable qualities. Self-pity is not one of them.", speaker: "Varys", wrong: ["Tyrion Lannister", "Illyrio Mopatis", "Petyr Baelish"], s: 5, hint: "A spymaster's tart refusal to let a self-exiled drunk wallow in guilt.", context: "Varys needling Tyrion out of his self-pity, trying to talk him into returning to the game from across the Narrow Sea." },
  { d: 1, fmt: "show", q: "Distrusting me was the wisest thing you've done since you climbed off your horse.", speaker: "Petyr Baelish", wrong: ["Varys", "Tywin Lannister", "Renly Baratheon"], s: 1, hint: "A courtier's backhanded compliment to a newly arrived Hand of the King.", context: "Littlefinger's reply to Ned Stark, after Ned admits he might have been wrong to distrust him." },
  { d: 1, fmt: "show", q: "There's no justice in the world, not unless we make it.", speaker: "Petyr Baelish", wrong: ["Varys", "Roose Bolton", "Sandor Clegane"], s: 5, hint: "A schemer's cold pep talk to a grieving young woman he's leading back north.", context: "Littlefinger urging Sansa to stop mourning and start acting, on the road toward Winterfell." },
  { d: 1, fmt: "show", q: "Ser Ilyn, bring me his head!", speaker: "Joffrey Baratheon", wrong: ["Tommen Baratheon", "Robert Baratheon", "Cersei Lannister"], s: 1, hint: "A cruel young king, ignoring every plea for mercy in front of a stunned crowd.", context: "Joffrey's shocking order at Eddard Stark's public execution, breaking his own promise of mercy." },
  { d: 1, fmt: "show", q: "I choose violence.", speaker: "Cersei Lannister", wrong: ["Jaime Lannister", "Tywin Lannister", "Qyburn"], s: 6, hint: "A proud queen's icy two-word answer when a former ally threatens her in the street.", context: "Cersei's cold reply to Lancel Lannister, now a zealot, warning her to stand down or face violence." },
  { d: 1, fmt: "show", q: "You want a whore, buy her. You want a queen, earn her.", speaker: "Cersei Lannister", wrong: ["Margaery Tyrell", "Daenerys Targaryen", "Olenna Tyrell"], s: 8, hint: "A queen's icy retort to a suitor who thought her grief made her an easy conquest.", context: "Cersei shutting down Euron Greyjoy's crude courtship in the throne room." },
  { d: 1, fmt: "show", q: "You're going to die tomorrow, Lord Bolton.", speaker: "Sansa Stark", wrong: ["Arya Stark", "Catelyn Stark", "Brienne of Tarth"], s: 6, hint: "A once-frightened girl, coldly promising her tormentor his ending the night before battle.", context: "Sansa's parting words to Ramsay Bolton on the eve of the Battle of the Bastards." },
  { d: 1, fmt: "show", q: "That's what happens to people who stand between Petyr and me.", speaker: "Lysa Arryn", wrong: ["Petyr Baelish", "Sansa Stark", "Robin Arryn"], s: 4, hint: "A jealous, unstable wife's threat, delivered while dangling her niece over a very long drop.", context: "Lysa's outburst at the Moon Door, accusing Sansa of trying to steal Petyr Baelish's affection." },
  { d: 1, fmt: "show", q: "You raped her. You murdered her. You killed her children.", speaker: "Oberyn Martell", wrong: ["Ellaria Sand", "Doran Martell", "Tyrion Lannister"], s: 4, hint: "A vengeful prince, forcing a monstrous knight to remember exactly who he murdered.", context: "Oberyn's demand during his trial-by-combat against the Mountain, avenging his sister at last." },
  { d: 1, fmt: "show", q: "I am not here to be queen of the ashes.", speaker: "Daenerys Targaryen", wrong: ["Missandei", "Tyrion Lannister", "Jorah Mormont"], s: 7, hint: "A queen refusing to burn the very city and people she means to rule.", context: "Daenerys's reply after Olenna Tyrell urges her to unleash her dragons on King's Landing without restraint." },
  { d: 1, fmt: "show", q: "I am not a khal. I will not choose three bloodriders. I choose you all!", speaker: "Daenerys Targaryen", wrong: ["Missandei", "Daario Naharis", "Jorah Mormont"], s: 6, hint: "A queen on dragonback, refusing to pick favorites among a khalasar that just watched her survive fire.", context: "Daenerys uniting the scattered Dothraki khalasars under her alone after walking out of the burning temple of the dosh khaleen." },
  { d: 1, fmt: "show", q: "I am the dragon's daughter. Those who would harm you will die screaming.", speaker: "Daenerys Targaryen", wrong: ["Viserys Targaryen", "Jorah Mormont", "Missandei"], s: 1, hint: "A newly widowed khaleesi, making a promise to the child she's carrying.", context: "Daenerys's vow after Khal Drogo's death, at the very end of the first season." },
  { d: 1, fmt: "show", q: "I don't care if he's a bastard. Ned Stark's blood runs through his veins. He's my king, from this day, until his last day.", speaker: "Lyanna Mormont", wrong: ["Maege Mormont", "Sansa Stark", "Yara Greyjoy"], s: 6, hint: "The North's youngest, fiercest lady, shaming a room full of grown lords into loyalty.", context: "Lyanna Mormont's speech at Winterfell, the first voice to declare Jon Snow King in the North." },
  { d: 1, fmt: "show", q: "What did Father used to say? Everything before the word 'but' is horseshit.", speaker: "Jon Snow", wrong: ["Robb Stark", "Tormund Giantsbane", "Samwell Tarly"], s: 7, hint: "A reluctant king, quoting his late father's blunt wisdom to his sister.", context: "Jon's response to Sansa's backhanded praise, recalling a lesson from Eddard Stark." },
  { d: 1, fmt: "show", q: "I did what I thought was right. And I got murdered for it.", speaker: "Jon Snow", wrong: ["Samwell Tarly", "Davos Seaworth", "Edd Tollett"], s: 6, hint: "A man freshly returned from the dead, summing up how that happened in one bitter sentence.", context: "Jon's blunt answer to Sansa, after his resurrection at Castle Black." },
  { d: 1, fmt: "show", q: "Why do you think I came all this way?", speaker: "Bran Stark", wrong: ["Jon Snow", "Tyrion Lannister", "Samwell Tarly"], s: 8, hint: "A boy who became something more, answering a question with a question.", context: "Bran's reply when Tyrion asks whether he would consider ruling the Six Kingdoms." },
  { d: 1, fmt: "show", q: "I have a tender spot in my heart for cripples, bastards and broken things.", speaker: "Tyrion Lannister", wrong: ["Bronn", "Varys", "Jaime Lannister"], s: 1, hint: "A dwarf explaining, to a skeptical King in the North, why he'd help a crippled boy at all.", context: "Tyrion's answer to Robb Stark, after sending Bran Stark a design for a saddle that could let him ride again." },
  { d: 1, fmt: "show", q: "Nothing's more hateful than failing to protect the one you love.", speaker: "Brienne of Tarth", wrong: ["Jaime Lannister", "Catelyn Stark", "Podrick Payne"], s: 5, hint: "A sworn shield, blaming herself for a king's death she couldn't stop.", context: "Brienne confessing her guilt over Renly's murder to Podrick Payne, on the road as Catelyn Stark's sworn sword." },
  { d: 1, fmt: "show", q: "I fear I'm a coward. My lord father always said so.", speaker: "Samwell Tarly", wrong: ["Jon Snow", "Grenn", "Pyp"], s: 3, hint: "A bookish brother of the Night's Watch, bluntly admitting his own worst fear to someone he trusts.", context: "Sam's confession to Gilly, reflecting on how his father always saw him." },
  { d: 1, fmt: "show", q: "I was never the biggest, never the strongest. But I was bravest, always. Until I met Missandei of Naath. Now I have fear.", speaker: "Grey Worm", wrong: ["Daario Naharis", "Jorah Mormont", "Barristan Selmy"], s: 7, hint: "An Unsullied commander, admitting that love has finally given him something to lose.", context: "Grey Worm's confession to Missandei about the one fear slavery never trained out of him." },
  { d: 1, fmt: "show", q: "If we don't put aside our enmities and band together, we will die, and then it won't matter whose skeleton sits on the Iron Throne.", speaker: "Davos Seaworth", wrong: ["Tyrion Lannister", "Jon Snow", "Jorah Mormont"], s: 7, hint: "A smuggler-turned-advisor, arguing for unity in a room full of rival queens and old enemies.", context: "Davos's plea at the Dragonpit summit in King's Landing, urging Cersei and Daenerys to set their war aside." },
  { d: 1, fmt: "show", q: "Good. Now, go fail again.", speaker: "Davos Seaworth", wrong: ["Jon Snow", "Melisandre", "Edd Tollett"], s: 6, hint: "A blunt, fatherly piece of advice from an advisor who's failed plenty himself.", context: "Davos's dry response after Jon Snow admits his last attempt at leadership got him killed." },
  { d: 1, fmt: "show", q: "Everything that's happened since — all this horror that's come to my family — it's all because I couldn't love a motherless child.", speaker: "Catelyn Stark", wrong: ["Lysa Arryn", "Cersei Lannister", "Sansa Stark"], s: 3, hint: "A grieving mother's private confession about the boy she could never bring herself to love.", context: "Catelyn's admission to Talisa about Jon Snow, and the promise to the gods she broke long ago." },
  { d: 1, fmt: "show", q: "Without question? No. I'd ask how much.", speaker: "Bronn", wrong: ["Jaime Lannister", "Sandor Clegane", "Podrick Payne"], s: 2, hint: "A pragmatic sellsword's honest answer to a question about murdering a baby.", context: "Bronn's blunt reply when Tyrion asks whether he'd kill an infant girl on command." },
  { d: 1, fmt: "show", q: "The strong live and the weak don't.", speaker: "Bronn", wrong: ["Tyrion Lannister", "Podrick Payne", "Jaime Lannister"], s: 8, hint: "A hired sword's cynical creed, offered as advice to the new king of the Six Kingdoms.", context: "Bronn's parting philosophy to Tyrion and the small council after being named Master of Coin." },
  { d: 1, fmt: "show", q: "Anyone can be killed.", speaker: "Arya Stark", wrong: ["Sansa Stark", "Brienne of Tarth", "The Waif"], s: 2, hint: "A disguised Stark girl, coolly correcting a Lannister lord's assumptions about her brother.", context: "Arya's answer to Tywin Lannister, when he asks if she believes the tales that Robb Stark can't be killed." },
  { d: 1, fmt: "show", q: "You used to be taller.", speaker: "Arya Stark", wrong: ["Sansa Stark", "Brienne of Tarth", "Yara Greyjoy"], s: 8, hint: "A little sister's dry greeting to a brother she hasn't seen in years.", context: "Arya's reunion with Jon Snow at Winterfell, teasing him after so long apart." },
  { d: 1, fmt: "show", q: "She's not our queen because she's the daughter of some king we never knew. She's the queen we chose.", speaker: "Missandei", wrong: ["Grey Worm", "Daario Naharis", "Jorah Mormont"], s: 7, hint: "A former slave, explaining why she follows this particular queen out of choice, not birthright.", context: "Missandei's explanation of why she and the freedmen who follow Daenerys do so willingly." },
  { d: 1, fmt: "show", q: "I can't fight for Robb and my father both.", speaker: "Theon Greyjoy", wrong: ["Yara Greyjoy", "Balon Greyjoy", "Robb Stark"], s: 2, hint: "A hostage-turned-son torn between the family that raised him and the family that bore him.", context: "Theon's justification to Bran Stark, after seizing Winterfell for the Iron Islands." },

  // ================= SHOW — EASY/HARD (reclassified from medium) =================
  { d: 1, fmt: "show", q: "Explain to me why it is more noble to kill ten thousand men in battle than a dozen at dinner.", speaker: "Tywin Lannister", wrong: ["Roose Bolton", "Walder Frey", "Petyr Baelish"], s: 3, hint: "A father justifying a wedding gone terribly wrong to his son.", context: "Tywin's cold logic to Tyrion, defending the Red Wedding as simple wartime pragmatism." },
  { d: 3, fmt: "show", q: "The absence of fear is how I know I'm right.", speaker: "Stannis Baratheon", wrong: ["Davos Seaworth", "Melisandre", "Renly Baratheon"], s: 2, hint: "A grim, dutiful claimant explaining his own certainty.", context: "Stannis's answer when asked if he's ever afraid of the choices he makes." },
  { d: 3, fmt: "show", q: "Nothing isn't better or worse than anything. Nothing is just nothing.", speaker: "Jaqen H'ghar", wrong: ["The Waif", "Syrio Forel", "Yoren of the Night's Watch"], s: 2, hint: "A riddling Braavosi's lesson about identity.", context: "Jaqen's cryptic correction to Arya, one of many small lessons about becoming 'no one.'" },
  { d: 1, fmt: "show", q: "Death is so terribly final, while life is full of possibilities.", speaker: "Petyr Baelish", wrong: ["Varys", "Roose Bolton", "Tywin Lannister"], s: 4, hint: "A schemer's dark comfort, offered to a grieving young woman.", context: "Littlefinger's words to Sansa, revealing just how coldly he weighs life and death." },
  { d: 3, fmt: "show", q: "We don't get to choose who we love.", speaker: "Oberyn Martell", wrong: ["Ellaria Sand", "Doran Martell", "Jaime Lannister"], s: 4, hint: "A Dornish prince, speaking with unusual tenderness to a Lannister.", context: "Oberyn's quiet admission to Tyrion, about family bonds that outlast old grudges." },
  { d: 1, fmt: "show", q: "Love is the death of duty.", speaker: "Maester Aemon", wrong: ["Jeor Mormont", "Samwell Tarly", "Qhorin Halfhand"], s: 3, hint: "A blind old maester's warning about the coldest of vows.", context: "Aemon's counsel to Jon Snow, on why the Night's Watch forbids marriage and family." },
  { d: 1, fmt: "show", q: "Any man who must say 'I am the king' is no true king.", speaker: "Tywin Lannister", wrong: ["Robert Baratheon", "Stannis Baratheon", "Kevan Lannister"], s: 1, hint: "A grandfather's harsh lesson for a boy on the Iron Throne.", context: "Tywin schooling young Joffrey on what real authority looks like." },
  { d: 1, fmt: "show", q: "The freedom of an ant is meaningless to a lion.", speaker: "Tywin Lannister", wrong: ["Cersei Lannister", "Jaime Lannister", "Kevan Lannister"], s: 6, hint: "A grandfather explaining power to a much gentler king.", context: "Tywin's lesson to Tommen about mercy, obligation, and the cost of ruling." },
  { d: 1, fmt: "show", q: "You're a good man. It's a pity you're not a dragon.", speaker: "Tywin Lannister", wrong: ["Olenna Tyrell", "Cersei Lannister", "Varys"], s: 4, hint: "A backhanded compliment from a father to his least-favored son.", context: "Tywin's grudging acknowledgment of Tyrion, wrapped in the usual insult." },
  { d: 1, fmt: "show", q: "I am the storm, the first storm, and the last.", speaker: "Stannis Baratheon", wrong: ["Robert Baratheon", "Renly Baratheon", "Davos Seaworth"], s: 2, hint: "A grim claimant naming himself after his own house's sigil.", context: "Stannis's proud declaration of who he is, against all doubters." },
  { d: 3, fmt: "show", q: "There's a beast in every man, and it stirs when you put a sword in his hand.", speaker: "Jorah Mormont", wrong: ["Barristan Selmy", "Daario Naharis", "Khal Drogo"], s: 1, hint: "An exiled knight's warning about the Dothraki way of war.", context: "Jorah cautioning Daenerys about what she's about to witness among Drogo's khalasar." },
  { d: 1, fmt: "show", q: "It's the family name that lives on. That's all that matters.", speaker: "Tywin Lannister", wrong: ["Cersei Lannister", "Jaime Lannister", "Olenna Tyrell"], s: 1, hint: "A patriarch lecturing his heir on what truly endures.", context: "Tywin's cold philosophy of legacy, delivered while skinning a deer in front of Jaime." },
  { d: 1, fmt: "show", q: "The Lannisters send their regards.", speaker: "Roose Bolton", wrong: ["Walder Frey", "Ramsay Bolton", "Tywin Lannister"], s: 3, hint: "Four quiet words, spoken just before a betrayal is completed.", context: "Roose Bolton's line to Robb Stark, the instant before the Red Wedding turns to slaughter." },
  { d: 3, fmt: "show", q: "The things we love destroy us every time, lad. Remember that.", speaker: "Craster", wrong: ["Jeor Mormont", "Qhorin Halfhand", "Mance Rayder"], s: 2, hint: "A grim word of advice from a man who keeps his own family as sacrifices.", context: "Craster's warning to Jon Snow at his isolated keep beyond the Wall." },
  { d: 3, fmt: "show", q: "You want a good man to be your enemy?", speaker: "Bronn", wrong: ["Jaime Lannister", "Sandor Clegane", "Tyrion Lannister"], s: 1, hint: "A pragmatic sellsword's counter-argument about loyalty and gold.", context: "Bronn explaining, with typical bluntness, why he fights for whoever pays him." },
  { d: 1, fmt: "show", q: "I understand the wisdom of what you did. But I did not love you any less.", speaker: "Olenna Tyrell", wrong: ["Margaery Tyrell", "Mace Tyrell", "Loras Tyrell"], s: 4, hint: "A grandmother's cold, loving farewell after a poisoning she helped arrange.", context: "The Queen of Thorns' parting words after Joffrey's death, spoken quietly to her granddaughter." },

  // ================= SHOW — HARD =================
  { d: 3, fmt: "show", q: "I never bet against a Lannister.", speaker: "Bronn", wrong: ["Jaime Lannister", "Podrick Payne", "Varys"], s: 1, hint: "A hired sword explaining why he's always chosen the winning side.", context: "Bronn's answer when asked whether he's confident about a fight he's about to join." },
  { d: 1, fmt: "show", q: "The Dothraki don't have a word for 'thank you.'", speaker: "Daenerys Targaryen", wrong: ["Jorah Mormont", "Irri", "Daario Naharis"], s: 1, hint: "A young khaleesi, still learning the customs of her new people.", context: "Daenerys explaining a small but telling detail of Dothraki culture." },
  { d: 3, fmt: "show", q: "A bird trapped in a cage would rather die than lose the ability to fly.", speaker: "Daario Naharis", wrong: ["Jorah Mormont", "Grey Worm", "Barristan Selmy"], s: 5, hint: "A sellsword's plea about a queen who's grown too cautious.", context: "Daario's argument to Daenerys, urging her not to rule from behind a locked door." },
  { d: 3, fmt: "show", q: "Give me ten good men and I'll hold this tower against an army.", speaker: "Alliser Thorne", wrong: ["Jeor Mormont", "Bowen Marsh", "Janos Slynt"], s: 4, hint: "A hard-bitten instructor's boast about castle defenses.", context: "Ser Alliser's brag to Jon Snow about the strength of Castle Black's fortifications." },
  { d: 3, fmt: "show", q: "You can't hide from me. I see you. I've always seen you.", speaker: "Melisandre", wrong: ["Quaithe", "Mirri Maz Duur", "The Night King"], s: 6, hint: "A red priestess's warning to a man trying to slip away in the dark.", context: "Melisandre confronting a deserter fleeing Castle Black, revealing how little escapes her sight." },

  // ================= SHOW — HARD (batch 2) =================
  { d: 1, fmt: "show", q: "A Dothraki wedding without at least three deaths is considered a dull affair.", speaker: "Illyrio Mopatis", wrong: ["Xaro Xhoan Daxos", "Doreah", "Viserys Targaryen"], s: 1, hint: "A wealthy Pentoshi host, dryly briefing a would-be king on wedding customs across the Narrow Sea.", context: "Illyrio's wry aside to Viserys ahead of Daenerys's wedding to Khal Drogo, warning him what counts as a peaceful Dothraki celebration." },
  { d: 3, fmt: "show", q: "When the sun rises in the west and sets in the east. When seas go dry and the mountains blow in the wind like leaves.", speaker: "Mirri Maz Duur", wrong: ["Doreah", "Irri", "Qotho"], s: 1, hint: "A captured healer, answering a khaleesi's question about a husband's fate with a list of impossibilities.", context: "Mirri's riddling prophecy of when Khal Drogo will return to himself — never — spoken after her blood magic during his final illness." },
  { d: 3, fmt: "show", q: "A cup of wine to honour the one true God.", speaker: "Maester Cressen", wrong: ["Davos Seaworth", "Melisandre", "Maester Aemon"], s: 2, hint: "An old maester at Dragonstone, offering a toast with a hidden second purpose.", context: "Cressen's toast to Melisandre, moments before his failed attempt to poison her — and himself — at Stannis's court." },
  { d: 3, fmt: "show", q: "By right of birth and blood, I do this day lay claim to the Iron Throne of Westeros.", speaker: "Matthos Seaworth", wrong: ["Davos Seaworth", "Stannis Baratheon", "Melisandre"], s: 2, hint: "A young squire, reading his king's proclamation aloud to an assembled fleet.", context: "Davos's son Matthos reads Stannis's formal claim to the throne — a declaration that also publicly exposes Cersei and Jaime's incest for the first time." },
  { d: 3, fmt: "show", q: "Your time with the wolves has made you weak.", speaker: "Balon Greyjoy", wrong: ["Theon Greyjoy", "Yara Greyjoy", "Euron Greyjoy"], s: 2, hint: "An Iron Islands lord, unimpressed by his returning son's mainland manners.", context: "Balon's cold greeting to Theon, back at Pyke for the first time since being sent to Winterfell as a ward." },
  { d: 3, fmt: "show", q: "I shall be silent as the grave.", speaker: "Grand Maester Pycelle", wrong: ["Qyburn", "Varys", "Maester Luwin"], s: 2, hint: "An aging Small Council member, promising discretion he has no real intention of keeping.", context: "Pycelle's oily assurance to Tyrion that he'll keep the Dorne marriage plot from Cersei — a promise he breaks almost immediately." },
  { d: 3, fmt: "show", q: "Gods help you, Theon Greyjoy. Now, you are truly lost.", speaker: "Rodrik Cassel", wrong: ["Maester Luwin", "Jory Cassel", "Vayon Poole"], s: 2, hint: "A castellan's final words, spoken to the young lord about to have him killed.", context: "Ser Rodrik's last line before his execution at Winterfell, ordered by Theon after his failed conquest turns to occupation." },
  { d: 3, fmt: "show", q: "The kind who serves his king, Imp!", speaker: "Meryn Trant", wrong: ["Boros Blount", "Mandon Moore", "Arys Oakheart"], s: 2, hint: "A Kingsguard knight, defending his own cruelty as simple obedience.", context: "Trant's retort to Tyrion after being caught beating Sansa on Joffrey's orders." },
  { d: 3, fmt: "show", q: "No one can survive in this world without help. No one.", speaker: "Jorah Mormont", wrong: ["Barristan Selmy", "Daario Naharis", "Missandei"], s: 2, hint: "An exiled knight, pleading with an increasingly guarded khaleesi not to shut out her advisors.", context: "Jorah's plea to Daenerys after she declares she no longer needs anyone's trust, following her brother's death." },
  { d: 3, fmt: "show", q: "Which one gave you the tougher fight, the cripple or the six-year-old?", speaker: "Yara Greyjoy", wrong: ["Balon Greyjoy", "Euron Greyjoy", "Aeron Greyjoy"], s: 2, hint: "An Iron Islands captain, mocking her brother's 'conquest' of a nearly empty castle.", context: "Yara's scathing question to Theon after he seizes Winterfell from two young Stark boys and boasts about it." },
  { d: 3, fmt: "show", q: "Someplace that isn't burning. North, might be. Could be.", speaker: "Sandor Clegane", wrong: ["Bronn", "Jaime Lannister", "Gregor Clegane"], s: 2, hint: "A deserting bodyguard, vague about his destination but very sure about the direction he's leaving.", context: "The Hound, abandoning his post mid-battle, tells Sansa where he's headed during the chaos of the Battle of the Blackwater." },
  { d: 3, fmt: "show", q: "I will shield your back and keep your counsel and give my life for yours if need be. I swear it by the old gods and the new.", speaker: "Brienne of Tarth", wrong: ["Podrick Payne", "Sandor Clegane", "Jaime Lannister"], s: 2, hint: "A sworn shield's exact oath of service, offered to a Stark daughter more than once.", context: "Brienne's oath, first sworn to Catelyn Stark after besting Ser Loras in a tournament — and later repeated word for word to Sansa in the North." },
  { d: 3, fmt: "show", q: "I smell a Crow.", speaker: "Tormund Giantsbane", wrong: ["Ygritte", "Styr", "Rattleshirt"], s: 3, hint: "A wildling raider's first words on finding a Night's Watch man among his captives.", context: "Tormund's introduction, sniffing out Jon Snow as a captive brought before Mance Rayder's wildling camp." },
  { d: 3, fmt: "show", q: "I am a godly man!", speaker: "Craster", wrong: ["Karl Tanner", "Rast", "Jeor Mormont"], s: 3, hint: "A man beyond the Wall, insisting on his own piety to guests who don't believe a word of it.", context: "Craster's indignant defense of himself to the mutinous Night's Watch men sheltering at his keep." },
  { d: 3, fmt: "show", q: "There's sawdust in the bread.", speaker: "Karl Tanner", wrong: ["Rast", "Craster", "Alliser Thorne"], s: 3, hint: "A disgruntled mutineer, unimpressed with his host's cooking.", context: "Karl's complaint at Craster's Keep, part of the tension that boils over into the Night's Watch mutiny." },
  { d: 3, fmt: "show", q: "Not murder, Your Grace. Vengeance.", speaker: "Rickard Karstark", wrong: ["Roose Bolton", "Robb Stark", "Torrhen Karstark"], s: 3, hint: "A grieving Northern lord, refusing to call his own revenge a crime.", context: "Karstark's unrepentant answer to Robb after murdering two young Lannister hostages in revenge for his sons' deaths." },
  { d: 3, fmt: "show", q: "The Gods love to reward a fool.", speaker: "Brynden Tully", wrong: ["Edmure Tully", "Hoster Tully", "Robb Stark"], s: 3, hint: "A blunt old knight, needling his nephew's poor luck with women.", context: "The Blackfish's dry aside to Catelyn about Edmure, at the Twins on the night of the Red Wedding." },
  { d: 3, fmt: "show", q: "The law is the law. The boy must die.", speaker: "Janos Slynt", wrong: ["Alliser Thorne", "Bowen Marsh", "Maester Aemon"], s: 4, hint: "A disgraced former City Watch commander, arguing for the harshest possible sentence at a hearing.", context: "Slynt's judgment at Jon Snow's trial before the Night's Watch officers, demanding execution for Jon's confessed vow-breaking." },
  { d: 3, fmt: "show", q: "We hold the gate!", speaker: "Grenn", wrong: ["Pyp", "Edd Tollett", "Alliser Thorne"], s: 4, hint: "A green Night's Watch recruit, refusing to abandon a doorway even as a giant bears down on it.", context: "Grenn's rallying cry to his brothers as a handful of defenders brace to hold Castle Black's gate against Mag the Mighty." },
  { d: 3, fmt: "show", q: "You don't have to remind me. He was my brother long before he was anything to you.", speaker: "Doran Martell", wrong: ["Ellaria Sand", "Oberyn Martell", "Areo Hotah"], s: 5, hint: "A patient prince, reminding a grieving lover whose loss came first.", context: "Doran's rebuke to Ellaria, who wants immediate war with the Lannisters after Oberyn's death." },
  { d: 3, fmt: "show", q: "We're not here to feed you. We're here to kill you.", speaker: "Obara Sand", wrong: ["Nymeria Sand", "Tyene Sand", "Ellaria Sand"], s: 5, hint: "One of Oberyn's daughters, finished with polite Dornish diplomacy.", context: "Obara's threat to Trystane Martell as the Sand Snakes move against House Martell's peace with the Lannisters." },
  { d: 1, fmt: "show", q: "She's good meat. Feed her to the hounds.", speaker: "Ramsay Bolton", wrong: ["Roose Bolton", "Walda Bolton", "Karl Tanner"], s: 6, hint: "A newly-made lord, deciding a captured attacker's fate without a flicker of hesitation.", context: "Ramsay's chillingly casual order after Osha's attempt to assassinate him fails." },
  { d: 3, fmt: "show", q: "This is my home. I was born in this castle.", speaker: "Brynden Tully", wrong: ["Edmure Tully", "Robb Stark", "Hoster Tully"], s: 6, hint: "An old knight, done running, holding the castle where he grew up.", context: "The Blackfish's refusal to abandon Riverrun even as a Lannister-Frey army lays siege to it." },
  { d: 3, fmt: "show", q: "They're laughing at us. I hear it in my sleep.", speaker: "Walder Frey", wrong: ["Roose Bolton", "Black Walder Rivers", "Lothar Frey"], s: 6, hint: "An aging lord, obsessed with how little respect his family commands from the rest of Westeros.", context: "Walder's paranoid complaint to his sons about the Freys' reputation, not long before his own death catches up with him." },
  { d: 3, fmt: "show", q: "On some level you understand that you're an evil man.", speaker: "Edmure Tully", wrong: ["Brynden Tully", "Robb Stark", "Roose Bolton"], s: 6, hint: "A reluctant lord, told to yield his own castle, taking a moment to size up the knight holding him hostage.", context: "Edmure's blunt assessment of Jaime Lannister, during their conversation as Jaime besieges Riverrun." },
  { d: 3, fmt: "show", q: "I've been around the world. I've seen everything, things you couldn't imagine, and this... this is the only thing I've ever seen that terrifies me.", speaker: "Euron Greyjoy", wrong: ["Yara Greyjoy", "Theon Greyjoy", "Harry Strickland"], s: 7, hint: "A boastful reaver, admitting real fear for perhaps the only time on screen.", context: "Euron's reaction to the captured wight brought before the assembled lords at the Dragonpit meeting in King's Landing." },
  { d: 3, fmt: "show", q: "I already have a queen.", speaker: "Randyll Tarly", wrong: ["Dickon Tarly", "Jaime Lannister", "Bronn"], s: 7, hint: "A stern Reach lord, refusing to bend the knee even with his life on the line.", context: "Randyll's defiant refusal of mercy after being captured following the Loot Train battle." },
  { d: 3, fmt: "show", q: "I didn't expect it to smell like that.", speaker: "Dickon Tarly", wrong: ["Randyll Tarly", "Bronn", "Jaime Lannister"], s: 7, hint: "A young Reach heir, unsettled by his first real taste of a dragon's handiwork.", context: "Dickon's shaken reaction to the aftermath of dragonfire on the battlefield after the Loot Train attack." },
  { d: 3, fmt: "show", q: "I know it. All of us who came with her from Essos, we believe in her.", speaker: "Missandei", wrong: ["Grey Worm", "Daario Naharis", "Barristan Selmy"], s: 7, hint: "A trusted advisor and translator, reassuring a worried commander their faith hasn't wavered.", context: "Missandei's reassurance to Grey Worm about their belief in Daenerys as her southern campaign hits setbacks." },
  { d: 3, fmt: "show", q: "Poor girl. The pox will take her within the year.", speaker: "Qyburn", wrong: ["Grand Maester Pycelle", "Maester Cressen", "Harry Strickland"], s: 8, hint: "The Queen's pet maester, making idle small talk about someone else's grim fate.", context: "Qyburn's offhand remark to Bronn about one of his companions, while delivering Cersei's offer on her behalf." },

  // ================= SHOW — EASY/HARD (reclassified from medium; originally moved from hard) =================
  { d: 1, fmt: "show", q: "I am the shield that guards the realms of men.", speaker: "Samwell Tarly", wrong: ["Tyrion Lannister", "Daenerys Targaryen", "Cersei Lannister"], s: 1, hint: "One line of an ancient vow, spoken by a reluctant new recruit.", context: "Part of the Night's Watch oath, recited in the godswood at Castle Black." },
  { d: 3, fmt: "show", q: "The dead are already here.", speaker: "Jon Snow", wrong: ["Samwell Tarly", "Tormund Giantsbane", "Beric Dondarrion"], s: 5, hint: "A grim warning about an enemy no one south of the Wall wants to believe in.", context: "Jon's blunt reply, trying to convince southern lords that the true threat isn't a rival claimant." },
  { d: 1, fmt: "show", q: "The next time you raise a hand to me will be the last time you have hands.", speaker: "Cersei Lannister", wrong: ["Tywin Lannister", "Tyrion Lannister", "Qyburn"], s: 5, hint: "A queen's cold threat, delivered to a zealot who mistook her for weak.", context: "Cersei's warning to the High Sparrow's followers, before her fortunes truly turned." },
  { d: 3, fmt: "show", q: "Sons are not a woman's only reason for living.", speaker: "Olenna Tyrell", wrong: ["Cersei Lannister", "Catelyn Stark", "Ellaria Sand"], s: 2, hint: "A sharp-tongued grandmother, unimpressed by another woman's grief.", context: "Olenna Tyrell's tart response, refusing to let a rival's sorrow go unanswered." },

  // ================= SHOW — EASY/HARD (reclassified from medium, batch 2) =================
  { d: 1, fmt: "show", q: "Everyone who isn't us is an enemy.", speaker: "Cersei Lannister", wrong: ["Tywin Lannister", "Joffrey Baratheon", "Margaery Tyrell"], s: 1, hint: "A mother's early lesson to her son about trusting only their own blood.", context: "Cersei's advice to a young Joffrey, warning him that even in-laws like the Starks are ultimately rivals." },
  { d: 1, fmt: "show", q: "My name is Reek. It rhymes with freak.", speaker: "Theon Greyjoy", wrong: ["Ramsay Bolton", "Roose Bolton", "Yara Greyjoy"], s: 4, hint: "A once-proud ironborn heir, reduced to reciting a name someone else forced on him.", context: "Theon, broken by Ramsay Bolton's torture, mutters the only identity he has left." },
  { d: 1, fmt: "show", q: "I'm a slow learner, it's true. But I learn.", speaker: "Sansa Stark", wrong: ["Arya Stark", "Margaery Tyrell", "Catelyn Stark"], s: 7, hint: "A once-naive girl, calmly baiting the manipulator who taught her the game.", context: "Sansa's reply to Petyr Baelish at his trial in Winterfell's great hall, just before his crimes are laid bare." },
  { d: 1, fmt: "show", q: "The lords of Westeros are sheep. Are you a sheep? No. You're a dragon. Be a dragon.", speaker: "Olenna Tyrell", wrong: ["Varys", "Tyrion Lannister", "Margaery Tyrell"], s: 7, hint: "A sharp-tongued grandmother warning a young queen not to let clever advisors soften her.", context: "Olenna's parting advice to Daenerys at Highgarden, urging her to trust her instincts over Tyrion and Varys." },
  { d: 1, fmt: "show", q: "It's better to be a coward for a minute, than dead for the rest of your life.", speaker: "Davos Seaworth", wrong: ["Bronn", "Jorah Mormont", "Tyrion Lannister"], s: 7, hint: "An old smuggler-turned-advisor quotes his own father's wisdom about knowing when to hold back.", context: "Davos's family saying, offered as counsel against a reckless plan beyond the Wall." },
  { d: 3, fmt: "show", q: "No, not death. I fear I never again see Missandei from the Island of Naath.", speaker: "Grey Worm", wrong: ["Daario Naharis", "Jorah Mormont", "Barristan Selmy"], s: 5, hint: "An Unsullied commander admits his one real fear isn't dying in battle.", context: "Grey Worm's quiet confession about what frightens him more than death." },
  { d: 3, fmt: "show", q: "A man of honor keeps his vows, even if he's serving a drunk or a lunatic.", speaker: "Barristan Selmy", wrong: ["Jorah Mormont", "Jaime Lannister", "Brynden Tully"], s: 3, hint: "An old, exiled knight explains why he kept serving kings he didn't respect.", context: "Barristan Selmy's explanation to Daenerys of the code that bound him to flawed kings for decades." },
  { d: 3, fmt: "show", q: "Death is the enemy. The first enemy and the last.", speaker: "Beric Dondarrion", wrong: ["Thoros of Myr", "Jon Snow", "Tormund Giantsbane"], s: 7, hint: "A knight brought back from death more times than he can count, describing what he's really fighting.", context: "Beric's answer to Jon Snow about purpose, during the mission beyond the Wall to capture a wight." },
  { d: 3, fmt: "show", q: "You died in that cave.", speaker: "Meera Reed", wrong: ["Osha", "Jojen Reed", "Sansa Stark"], s: 7, hint: "A grieving companion says a hard goodbye to the boy she once helped carry north.", context: "Meera's farewell to Bran at Winterfell, mourning the friend who disappeared into the Three-Eyed Raven." },
  { d: 1, fmt: "show", q: "There is only one war that matters. The Great War. And it is here.", speaker: "Jon Snow", wrong: ["Daenerys Targaryen", "Davos Seaworth", "Tyrion Lannister"], s: 7, hint: "A King in the North tries to convince southern lords that a rival throne isn't the real threat.", context: "Jon's blunt declaration at the Dragonpit summit, trying to unite old enemies against the army of the dead." },
  { d: 3, fmt: "show", q: "We do not mutilate little girls for vengeance.", speaker: "Doran Martell", wrong: ["Oberyn Martell", "Ellaria Sand", "Areo Hotah"], s: 5, hint: "A wheelchair-bound prince refuses his paramour's calls for retaliation against a child.", context: "Doran Martell's refusal to let Ellaria harm Myrcella Baratheon after Oberyn's death." },
  { d: 3, fmt: "show", q: "It's always changing, who we're supposed to love and who we're not. The only thing that stays the same is that we want who we want.", speaker: "Ellaria Sand", wrong: ["Oberyn Martell", "Tyene Sand", "Doran Martell"], s: 4, hint: "A prince's paramour muses on desire while he watches from across the room.", context: "Ellaria's reflection on love, part of her and Oberyn's introduction in King's Landing." },
  { d: 3, fmt: "show", q: "Strip away the gold and the ornaments, knock down the statues and the pillars, and this is what remains. Something simple, and solid, and true.", speaker: "The High Sparrow", wrong: ["Septa Unella", "Lancel Lannister", "The High Septon"], s: 5, hint: "A barefoot religious leader explains what's left once wealth and status are stripped away.", context: "The High Sparrow's sermon to Margaery, describing the plain faith underneath the Great Sept's finery." },
  { d: 1, fmt: "show", q: "I never loved my brothers. A sad thing for a man to admit, but it's true. You were the brother I chose.", speaker: "Robert Baratheon", wrong: ["Eddard Stark", "Stannis Baratheon", "Renly Baratheon"], s: 1, hint: "A weary king admits to an old friend which of his siblings he never really cared for.", context: "Robert's rare moment of honesty with Ned Stark, about the family he was born into versus the friend he chose." },
  { d: 3, fmt: "show", q: "I now proclaim Cersei of the House Lannister, First of Her Name, Queen of the Andals and the First Men, Protector of the Seven Kingdoms. Long may she reign.", speaker: "Qyburn", wrong: ["Grand Maester Pycelle", "The High Septon", "Kevan Lannister"], s: 7, hint: "A disgraced maester turned kingmaker formally announces a new ruler in the throne room.", context: "Qyburn presides over Cersei's coronation after the deaths of all three of her children." },
  { d: 1, fmt: "show", q: "I've won every battle. But I'm losing this war.", speaker: "Robb Stark", wrong: ["Catelyn Stark", "Jon Snow", "Robert Baratheon"], s: 3, hint: "A young king undefeated on the battlefield admits the bigger fight is already slipping away.", context: "Robb's grim acknowledgment, late in the War of the Five Kings, that victories in the field haven't won him the crown." },
  { d: 1, fmt: "show", q: "All my life men like you have sneered at me. And all my life I've been knocking men like you into the dust.", speaker: "Brienne of Tarth", wrong: ["Sandor Clegane", "Jaime Lannister", "Loras Tyrell"], s: 1, hint: "A big, unglamorous woman answers years of mockery by winning a melee in front of a prince.", context: "Brienne's retort after besting knights who underestimated her at Renly's tournament." },
  { d: 3, fmt: "show", q: "Just a boy. He came trading with his brothers. He had red hair like me. Kissed by fire.", speaker: "Ygritte", wrong: ["Osha", "Karsi", "Gilly"], s: 3, hint: "A wildling archer, quieter than usual, remembers a boy from her past who shared her mark.", context: "Ygritte tells Jon about someone she once knew — also 'kissed by fire,' like her." },
  { d: 1, fmt: "show", q: "I only do what my Lord commands.", speaker: "Melisandre", wrong: ["Selyse Baratheon", "Stannis Baratheon", "Davos Seaworth"], s: 5, hint: "A red priestess, coldly certain her god required a terrible sacrifice.", context: "Melisandre's justification after Shireen Baratheon is burned at the stake." },
  { d: 1, fmt: "show", q: "You've changed, Little Bird. None of it would have happened if you'd left King's Landing with me.", speaker: "Sandor Clegane", wrong: ["Petyr Baelish", "Jaime Lannister", "Brienne of Tarth"], s: 8, hint: "A scarred bodyguard, reunited with the girl he once tried to take north, reflects on what she lost without him.", context: "The Hound's fireside conversation with Sansa at Winterfell, about how differently her life might have gone." },
  { d: 1, fmt: "show", q: "I don't plan on knitting by the fire while men fight for me. I might be small, Lord Glover, but I am every bit as much a Northerner as you.", speaker: "Lyanna Mormont", wrong: ["Sansa Stark", "Yara Greyjoy", "Maege Mormont"], s: 7, hint: "The youngest lady of a Bear Island house refuses to be sidelined from the coming fight.", context: "Lyanna Mormont's sharp rebuke to a Northern lord who suggested the women stay home." },
  { d: 3, fmt: "show", q: "Catelyn Stark would be proud. You kept your vow.", speaker: "Podrick Payne", wrong: ["Jaime Lannister", "Bronn", "Davos Seaworth"], s: 6, hint: "A loyal squire-turned-fighter praises the honor of the woman he now travels with.", context: "Podrick's quiet compliment to Brienne, about how faithfully she's honored her promise to Catelyn Stark." },
  { d: 3, fmt: "show", q: "I'm only here because my father grabbed my mother instead of the girl next to her in the tavern.", speaker: "Gendry", wrong: ["Hot Pie", "Lommy Greenhands", "Podrick Payne"], s: 2, hint: "A blacksmith's apprentice shrugs off his own royal blood with dark humor.", context: "Gendry's self-deprecating explanation to Arya of how he came to be born a king's bastard." },

  // ================= BOOK — EASY =================
  { d: 1, fmt: "book", q: "When you play the game of thrones, you win or you die. There is no middle ground.", speaker: "Cersei Lannister", wrong: ["Tywin Lannister", "Petyr Baelish", "Varys"], b: 1, hint: "Said by a queen who believes mercy is a weakness.", context: "Cersei's warning to Ned Stark in his own solar, laying out the only two outcomes she recognizes." },
  { d: 1, fmt: "book", q: "A reader lives a thousand lives before he dies. The man who never reads lives only one.", speaker: "Jojen Reed", wrong: ["Meera Reed", "Samwell Tarly", "Maester Luwin"], b: 2, hint: "A young crannogman, wise well beyond his years, speaking to Bran.", context: "Jojen's gentle argument for why Bran should keep reading, even grounded and grieving." },
  { d: 1, fmt: "book", q: "The things I do for love.", speaker: "Jaime Lannister", wrong: ["Cersei Lannister", "Robert Baratheon", "Renly Baratheon"], b: 1, hint: "Said with a shrug, right before a shove from a tower window.", context: "Jaime's remark to a stunned Bran Stark, moments before Bran's fall." },
  { d: 1, fmt: "book", q: "The man who passes the sentence should swing the sword.", speaker: "Eddard Stark", wrong: ["Robert Baratheon", "Robb Stark", "Rodrik Cassel"], b: 1, hint: "A northern lord's rule about facing what you condemn.", context: "Ned's own reasoning, given to Bran, for beheading a deserter himself." },
  { d: 1, fmt: "book", q: "The night is dark and full of terrors.", speaker: "Melisandre", wrong: ["Davos Seaworth", "Tywin Lannister", "Stannis Baratheon"], b: 2, hint: "A red priestess's prayer, spoken in praise of the Lord of Light.", context: "Melisandre's ritual phrase, invoked in devotion across the second and third books." },
  { d: 1, fmt: "book", q: "What is honor compared to a woman's love?", speaker: "Maester Aemon", wrong: ["Jeor Mormont", "Samwell Tarly", "Qhorin Halfhand"], b: 3, hint: "A blind old maester's meditation on the vow he made long ago.", context: "Aemon's words to Jon Snow about the pull of love against a sworn duty." },
  { d: 1, fmt: "book", q: "The dragon does not concern himself with the opinions of the sheep.", speaker: "Daenerys Targaryen", wrong: ["Viserys Targaryen", "Aerys II Targaryen", "Rhaegar Targaryen"], b: 1, hint: "A young khaleesi's proud claim to a bloodline of fire.", context: "Daenerys's declaration of Targaryen indifference to the judgment of lesser men." },
  { d: 1, fmt: "book", q: "The lone wolf dies, but the pack survives.", speaker: "Eddard Stark", wrong: ["Catelyn Stark", "Benjen Stark", "Robb Stark"], b: 1, hint: "A father's lesson to his children, about sticking together.", context: "Ned's words, recalled by his children long after he can no longer say them himself." },
  { d: 1, fmt: "book", q: "Give me a good horse, a good sword, and a soft bed to die on, when the time comes.", speaker: "Sandor Clegane", wrong: ["Bronn", "Jaime Lannister", "Jorah Mormont"], b: 2, hint: "A scarred, cynical fighter naming the only comforts he still wants.", context: "The Hound's blunt statement of what little he still asks of life." },
  { d: 1, fmt: "book", q: "Kill the boy, and let the man be born.", speaker: "Maester Aemon", wrong: ["Jeor Mormont", "Samwell Tarly", "Bowen Marsh"], b: 3, hint: "A blind old maester's hard advice to a young man about to take command.", context: "Aemon's counsel to Jon Snow, urging him to set aside old loves for the sake of duty." },
  { d: 1, fmt: "book", q: "I am the blood of the dragon. I must be strong.", speaker: "Daenerys Targaryen", wrong: ["Viserys Targaryen", "Rhaegar Targaryen", "Aerys II Targaryen"], b: 1, hint: "A young woman convincing herself she can survive what's coming.", context: "Daenerys's private mantra, repeated to steady herself through fear early in the first book." },

  // ================= BOOK — EASY (batch 2) =================
  { d: 1, fmt: "book", q: "A mind needs books as a sword needs a whetstone, if it is to keep its edge.", speaker: "Tyrion Lannister", wrong: ["Samwell Tarly", "Maester Luwin", "Varys"], b: 1, hint: "A dwarf's advice to a bastard boy about to take the black.", context: "Tyrion's parting counsel to Jon Snow on the road to the Wall, delivered with his usual dry wit." },
  { d: 1, fmt: "book", q: "Never forget what you are, for surely the world will not. Make it your strength. Then it can never be your weakness. Armour yourself in it, and it will never be used to hurt you.", speaker: "Tyrion Lannister", wrong: ["Jaime Lannister", "Bronn", "Varys"], b: 1, hint: "A dwarf's hard-won wisdom about being a bastard, offered at Winterfell.", context: "Tyrion's advice to Jon Snow at the welcoming feast, about turning the shame of his birth into something unbreakable." },
  { d: 1, fmt: "book", q: "That is the only time a man can be brave.", speaker: "Eddard Stark", wrong: ["Robert Baratheon", "Benjen Stark", "Robb Stark"], b: 1, hint: "A father's answer when his young son asks whether courage and fear can coexist.", context: "Ned's reply to Bran, who has just asked if a man can still be brave when he's afraid — a lesson Bran carries with him long after." },
  { d: 1, fmt: "book", q: "And I have a tender spot in my heart for cripples and bastards and broken things.", speaker: "Tyrion Lannister", wrong: ["Jaime Lannister", "Bronn", "Varys"], b: 1, hint: "A dwarf explaining, to a suspicious mother, why he wants to help her crippled son.", context: "Tyrion's answer to Catelyn Stark at Winterfell, when she asks why he'd bother designing a saddle for Bran." },
  { d: 1, fmt: "book", q: "Oh, my sweet summer child, what do you know of fear? Fear is for the winter, my little lord, when the snows fall a hundred feet deep.", speaker: "Old Nan", wrong: ["Catelyn Stark", "Septa Mordane", "Maester Luwin"], b: 1, hint: "An old woman's answer when a bedridden boy claims he wants a scary story.", context: "Old Nan's chilling reply to Bran, who insists he wants the frightening tales, not the comforting ones." },
  { d: 1, fmt: "book", q: "Life is not a song, sweetling. You may learn that one day to your sorrow.", speaker: "Petyr Baelish", wrong: ["Sandor Clegane", "Varys", "Tywin Lannister"], b: 1, hint: "A schemer's cynical correction to a girl who still believes in songs and heroes.", context: "Littlefinger's remark to Sansa at a tourney, puncturing her romantic notions of knighthood." },
  { d: 1, fmt: "book", q: "I only know she was the one thing I ever wanted. Someone took her away from me, and seven kingdoms couldn't fill the hole she left behind.", speaker: "Robert Baratheon", wrong: ["Eddard Stark", "Jaime Lannister", "Stannis Baratheon"], b: 1, hint: "A king's rare moment of honesty about the woman he never stopped mourning.", context: "Robert's confession to Ned about Lyanna Stark, the grief beneath his crown that even a throne couldn't cure." },
  { d: 1, fmt: "book", q: "A Dothraki wedding without at least three deaths is considered a dull affair.", speaker: "Illyrio Mopatis", wrong: ["Jorah Mormont", "Viserys Targaryen", "Doreah"], b: 1, hint: "A fat magister's wry warning about what to expect at a khal's wedding feast.", context: "Illyrio's remark about Dothraki wedding customs, before Daenerys's own marriage to Khal Drogo." },
  { d: 1, fmt: "book", q: "I am not threatening the king, ser, I am educating my nephew.", speaker: "Tyrion Lannister", wrong: ["Bronn", "Jaime Lannister", "Varys"], b: 2, hint: "A dwarf's cool reply after a Kingsguard accuses him of menacing the boy king.", context: "Tyrion's retort to Ser Boros Blount, moments before ordering his own men to make an actual threat, for comparison." },
  { d: 1, fmt: "book", q: "So many vows. They make you swear and swear. Defend the king. Obey the king. Keep his secrets. Do his bidding. Your life for his. But obey your father. Love your sister. Protect the innocent. Defend the weak. Respect the gods. Obey the laws. It's too much. No matter what you do, you're forsaking one vow or the other.", speaker: "Jaime Lannister", wrong: ["Barristan Selmy", "Eddard Stark", "Brienne of Tarth"], b: 2, hint: "A prisoner's weary complaint about the impossible math of knighthood.", context: "Jaime's outburst to Catelyn Stark at Riverrun, defending — and half-confessing — why he's broken so many of his own oaths." },
  { d: 1, fmt: "book", q: "Courtesy is a lady's armor.", speaker: "Sansa Stark", wrong: ["Margaery Tyrell", "Catelyn Stark", "Septa Mordane"], b: 2, hint: "A captive girl's answer when accused of hiding behind good manners.", context: "Sansa's reply to Tyrion at court, after he tells her she uses courtesy the way a castle uses its walls." },
  { d: 1, fmt: "book", q: "Renly offered me a peach. At our parley. Mocked me, defied me, threatened me, and offered me a peach.", speaker: "Stannis Baratheon", wrong: ["Robert Baratheon", "Davos Seaworth", "Renly Baratheon"], b: 2, hint: "A grim claimant's baffled complaint about his brother's strange parting gift.", context: "Stannis recounting his tense meeting with Renly before Storm's End, still stuck on the absurdity of the fruit." },
  { d: 1, fmt: "book", q: "It is as I feared. The green lands have made you soft, and the Starks have made you theirs.", speaker: "Balon Greyjoy", wrong: ["Aeron Greyjoy", "Victarion Greyjoy", "Euron Greyjoy"], b: 2, hint: "A hard father's cold verdict on the son who's just come home.", context: "Balon's judgment of Theon upon his return to Pyke, unimpressed by the young man the mainland made of him." },
  { d: 1, fmt: "book", q: "I was trying to win the throne to save the kingdom, when I should have been trying to save the kingdom to win the throne.", speaker: "Stannis Baratheon", wrong: ["Davos Seaworth", "Jon Snow", "Robert Baratheon"], b: 3, hint: "A grim king's rare admission that he had his priorities backwards.", context: "Stannis's confession to Jon Snow at Castle Black, weighing his own ambition against the realm's actual needs." },
  { d: 1, fmt: "book", q: "Free folk don't follow names, or little cloth animals sewn on a tunic. They follow strength. They follow the man.", speaker: "Mance Rayder", wrong: ["Tormund Giantsbane", "Qhorin Halfhand", "Jon Snow"], b: 3, hint: "The King-Beyond-the-Wall explaining why southern titles mean nothing to his people.", context: "Words Jon recalls Mance telling him, about what it actually takes to lead the free folk." },
  { d: 1, fmt: "book", q: "Girl or boy, we fight our battles, but the gods let us choose our weapons.", speaker: "Oberyn Martell", wrong: ["Doran Martell", "Areo Hotah", "Jaime Lannister"], b: 3, hint: "A Dornish prince's answer about why his daughters are trained as fighters too.", context: "Oberyn's explanation of Dornish custom, where a weapon can be a spear — or something else entirely." },
  { d: 1, fmt: "book", q: "There is entirely too much tut-tutting in this realm, if you ask me. All these kings would do a deal better if they put down their swords and listened to their mothers.", speaker: "Olenna Tyrell", wrong: ["Cersei Lannister", "Margaery Tyrell", "Catelyn Stark"], b: 3, hint: "A sharp-tongued grandmother's blunt review of every king currently at war.", context: "The Queen of Thorns, unimpressed as ever, offering her opinion on how the Seven Kingdoms ought to be run." },
  { d: 1, fmt: "book", q: "Some battles are won with swords and spears, others with quills and ravens.", speaker: "Tywin Lannister", wrong: ["Kevan Lannister", "Varys", "Petyr Baelish"], b: 3, hint: "A patriarch's reminder that ink can accomplish what steel can't.", context: "Tywin's cool observation about the other ways a war gets fought, beyond the battlefield." },
  { d: 1, fmt: "book", q: "A son for a son, heh. But that's a grandson . . . and he never was much use.", speaker: "Walder Frey", wrong: ["Roose Bolton", "Black Walder Rivers", "Lothar Frey"], b: 3, hint: "An old, callous lord's dismissive joke about one of his own grandsons.", context: "Walder Frey's characteristically cold remark, weighing a family death like an accounting error." },
  { d: 1, fmt: "book", q: "Widow's Wail was not meant for slicing pies.", speaker: "Margaery Tyrell", wrong: ["Olenna Tyrell", "Cersei Lannister", "Loras Tyrell"], b: 3, hint: "A new bride's dry aside about her husband's habit of misusing a priceless sword.", context: "Margaery's remark at the feast, about Joffrey putting his new Valyrian steel blade to a rather undignified use." },
  { d: 1, fmt: "book", q: "I count no day as lived unless I have loved a woman, slain a foeman, and eaten a fine meal.", speaker: "Daario Naharis", wrong: ["Jorah Mormont", "Khal Drogo", "Grey Worm"], b: 3, hint: "A gold-toothed sellsword captain's cheerful personal philosophy.", context: "Daario introducing himself, and his priorities, to Daenerys's court in his usual swaggering style." },
  { d: 1, fmt: "book", q: "Every flight begins with a fall.", speaker: "The Three-Eyed Raven", wrong: ["Bran Stark", "Jojen Reed", "Old Nan"], b: 3, hint: "A voice in a boy's recurring dream, encouraging him to trust his wings.", context: "Words spoken to Bran in his dreams of flying as a three-eyed crow, long before he understands what they mean." },
  { d: 1, fmt: "book", q: "The gods made men to fight, and women to bear children. A woman's war is in the birthing bed.", speaker: "Randyll Tarly", wrong: ["Balon Greyjoy", "Roose Bolton", "Tywin Lannister"], b: 4, hint: "A hard, unbending lord's rigid view of where a woman belongs, said to a lady knight.", context: "Randyll Tarly's blunt dismissal of Brienne of Tarth's chosen path, at Maidenpool." },
  { d: 1, fmt: "book", q: "Vengeance. Justice. Fire and blood.", speaker: "Doran Martell", wrong: ["Oberyn Martell", "Ellaria Sand", "Areo Hotah"], b: 4, hint: "A patient, gout-crippled prince finally naming what he's wanted all along.", context: "Doran's whispered answer to his daughter Arianne, revealing the long game he's played since his sister Elia's death." },
  { d: 1, fmt: "book", q: "Crown me, for peace and victory. Or crown my uncle, for more war and more defeat. What will you have, ironmen?", speaker: "Asha Greyjoy", wrong: ["Victarion Greyjoy", "Euron Greyjoy", "Theon Greyjoy"], b: 4, hint: "A kingsmoot candidate's blunt pitch, framed as a simple choice between two futures.", context: "Asha Greyjoy's appeal to the assembled ironborn at the kingsmoot, arguing her case against her uncle Victarion." },
  { d: 1, fmt: "book", q: "The choice is yours, brother. Live a thrall or die a king. Do you dare to fly?", speaker: "Euron Greyjoy", wrong: ["Victarion Greyjoy", "Balon Greyjoy", "Aeron Greyjoy"], b: 4, hint: "A one-eyed sea captain's taunting offer to a brother he considers weak.", context: "Euron's provocation, framing submission and death as the only two choices on the table." },
  { d: 1, fmt: "book", q: "Knowledge is a weapon, Jon. Arm yourself well before you ride forth to battle.", speaker: "Melisandre", wrong: ["Maester Aemon", "Samwell Tarly", "Davos Seaworth"], b: 5, hint: "A red priestess's warning to a new Lord Commander, about fighting an enemy from the past.", context: "Melisandre's counsel to Jon Snow at Castle Black, urging him to learn from history before making his next move." },
  { d: 1, fmt: "book", q: "Two gods are with me now. No foe can stand before two gods.", speaker: "Victarion Greyjoy", wrong: ["Aeron Greyjoy", "Euron Greyjoy", "Balon Greyjoy"], b: 5, hint: "An ironborn captain's new, doubled confidence after a priest's fire ritual.", context: "Victarion's private boast, sailing for Meereen with both the Drowned God and a red priest's magic supposedly on his side." },
  { d: 1, fmt: "book", q: "The strongest trees are rooted in the dark places of the earth. Darkness will be your cloak, your shield, your mother's milk.", speaker: "The Three-Eyed Raven", wrong: ["Bran Stark", "Jojen Reed", "Leaf"], b: 5, hint: "A voice from deep beneath a weirwood tree, telling a crippled boy not to fear the dark.", context: "Words spoken to Bran in the cave beyond the Wall, about the strength he'll need to find underground." },
  { d: 1, fmt: "book", q: "Bear Island knows no king but the King in the North, whose name is Stark.", speaker: "Lyanna Mormont", wrong: ["Robb Stark", "Jon Snow", "Sansa Stark"], b: 5, hint: "A young, unbending lady's terse reply to a king demanding her allegiance.", context: "The response Bear Island sends back to Stannis Baratheon's letter, refusing to bend the knee." },
  { d: 1, fmt: "book", q: "And what lesson can we draw from Volantene history? If you want to conquer the world, you best have dragons.", speaker: "Tyrion Lannister", wrong: ["Illyrio Mopatis", "Jorah Mormont", "Varys"], b: 5, hint: "A captive dwarf's dry lesson about what it actually takes to conquer a continent.", context: "Tyrion's cynical little history lecture on his long road east toward Daenerys and her dragons." },
  { d: 1, fmt: "book", q: "You are the blood of the dragon. You can make a hat.", speaker: "Tyrion Lannister", wrong: ["Varys", "Illyrio Mopatis", "Jorah Mormont"], b: 5, hint: "A dwarf's sarcastic private joke about a phrase he's heard a certain queen use.", context: "Tyrion mocking Daenerys's own words about dragon's blood, from the miserable safety of his own head." },
  { d: 1, fmt: "book", q: "I know nothing, Ygritte. And perhaps I never will.", speaker: "Jon Snow", wrong: ["Samwell Tarly", "Tormund Giantsbane", "Bowen Marsh"], b: 5, hint: "A Lord Commander's private, aching echo of a wildling woman's favorite tease.", context: "Jon's own thought, long after Ygritte's death, admitting she might have been right about him after all." },
  { d: 1, fmt: "book", q: "Perhaps I cannot make my people good, but I should at least try to make them a little less bad.", speaker: "Daenerys Targaryen", wrong: ["Missandei", "Barristan Selmy", "Tyrion Lannister"], b: 5, hint: "A queen's quiet, lowered expectations about the people she's sworn to rule.", context: "Daenerys's private thought while wrestling with the impossible task of governing Meereen." },
  { d: 1, fmt: "book", q: "Men can always fight, Your Grace. Ask rather if we can win. Dying is easy, but victory comes hard.", speaker: "Barristan Selmy", wrong: ["Jorah Mormont", "Grey Worm", "Daario Naharis"], b: 5, hint: "An old knight's blunt correction when his queen asks only whether her men will fight.", context: "Barristan Selmy's counsel to Daenerys in Meereen, reframing the real question before a battle." },
  { d: 1, fmt: "book", q: "I was a better smuggler than a knight, a better knight than a King's Hand, a better King's Hand than a husband.", speaker: "Davos Seaworth", wrong: ["Stannis Baratheon", "Jon Snow", "Melisandre"], b: 5, hint: "An onion smuggler turned lord's own harsh scorecard on himself.", context: "A private admission from Davos, ranking his own failures across every role he's ever held." },
  { d: 1, fmt: "book", q: "He can take my fingers and my toes, he can put out my eyes and slice my ears off, but he cannot take my wits unless I let him.", speaker: "Theon Greyjoy", wrong: ["Balon Greyjoy", "Euron Greyjoy", "Ramsay Bolton"], b: 5, hint: "A broken prisoner's last private claim to anything still his own.", context: "Theon's silent defiance, deep in his captivity, refusing to surrender the one thing left that's truly his." },
  { d: 1, fmt: "book", q: "Your false king is dead, bastard. He and all his host were smashed in seven days of battle. I have his magic sword. Tell his red whore.", speaker: "Ramsay Bolton", wrong: ["Roose Bolton", "Theon Greyjoy", "Walder Frey"], b: 5, hint: "A cruel lord's taunting letter, sent north to gloat over a rival's defeat.", context: "The opening lines of the letter Ramsay sends to Castle Black, needling Jon Snow with claims about Stannis's fate." },

  // ================= BOOK — EASY/HARD (reclassified from medium) =================
  { d: 1, fmt: "book", q: "A man who fears losing has already lost.", speaker: "Jaqen H'ghar", wrong: ["Syrio Forel", "The Waif", "Brynden Tully"], b: 2, hint: "A Braavosi assassin's lesson about confidence and control.", context: "One of Jaqen's quiet lessons to Arya, about facing danger without flinching." },
  { d: 3, fmt: "book", q: "The best confessions are written in blood.", speaker: "Petyr Baelish", wrong: ["Varys", "Tywin Lannister", "Roose Bolton"], b: 3, hint: "A schemer explaining why a written confession alone was never going to be believed.", context: "Littlefinger's remark about how he secured Tyrion's downfall — and no one's forgiveness." },
  { d: 1, fmt: "book", q: "Fear cuts deeper than swords.", speaker: "Syrio Forel", wrong: ["Jaqen H'ghar", "The Waif", "Ilyn Payne"], b: 1, hint: "A 'water dancing' master's teaching about the true danger in any fight.", context: "Syrio's lesson to Arya about courage, delivered long before his own last stand." },
  { d: 1, fmt: "book", q: "You know nothing, Jon Snow.", speaker: "Ygritte", wrong: ["Osha", "Gilly", "Craster"], b: 3, hint: "A wildling's running tease, said again and again in the books too.", context: "Ygritte's refrain to Jon, mocking his ignorance of the free folk's world." },
  { d: 1, fmt: "book", q: "What do we say to the god of death?", speaker: "Syrio Forel", wrong: ["Jaqen H'ghar", "Yoren of the Night's Watch", "The Waif"], b: 1, hint: "A dancing master's question, answered with a single word.", context: "Syrio's teaching to Arya — the question that becomes her own quiet mantra, 'not today.'" },

  // ================= BOOK — EASY/HARD (reclassified from medium, batch 2) =================
  { d: 1, fmt: "book", q: "I seldom fling children off the tops of towers to improve their health. Yes, I meant for him to die.", speaker: "Jaime Lannister", wrong: ["Tyrion Lannister", "Cersei Lannister", "Tywin Lannister"], b: 2, hint: "A captive knight's darkly sarcastic non-denial, given to the mother of the boy he pushed.", context: "Jaime's cutting reply to Catelyn Stark in his cell at Riverrun, when she finally asks him outright about Bran's fall." },
  { d: 1, fmt: "book", q: "I crossed a thousand leagues to come to you, and lost the best part of me along the way. Don't tell me to leave.", speaker: "Jaime Lannister", wrong: ["Sandor Clegane", "Robb Stark", "Jorah Mormont"], b: 3, hint: "A one-handed knight, refusing to let go of the woman he just risked everything for.", context: "Jaime's words to Brienne at Harrenhal, just after climbing into the bear pit to save her and losing his sword hand." },
  { d: 3, fmt: "book", q: "Most have been forgotten. Most deserve to be forgotten. The heroes will always be remembered. The best. The best and the worst. And a few who were a bit of both.", speaker: "Jaime Lannister", wrong: ["Barristan Selmy", "Brienne of Tarth", "Eddard Stark"], b: 4, hint: "A Kingsguard knight musing privately on his own place among centuries of white cloaks.", context: "Jaime's reflection, in his own point-of-view chapter, on the long and uneven history of the Kingsguard." },
  { d: 3, fmt: "book", q: "It was that white cloak that soiled me, not the other way around.", speaker: "Jaime Lannister", wrong: ["Barristan Selmy", "Sandor Clegane", "Brienne of Tarth"], b: 3, hint: "A captive knight's sharp retort to a noblewoman who calls him oathbreaker.", context: "Jaime's reply to Catelyn Stark, when she accuses him of dishonoring the white cloak of the Kingsguard." },
  { d: 1, fmt: "book", q: "My sister has mistaken me for a mushroom. She keeps me in the dark and feeds me shit.", speaker: "Tyrion Lannister", wrong: ["Jaime Lannister", "Varys", "Bronn"], b: 3, hint: "A prisoner dwarf's bitter joke about his own sister's hospitality.", context: "Tyrion's mordant complaint about the conditions of his confinement, after Cersei has him locked away." },
  { d: 1, fmt: "book", q: "Remember this, boy: all dwarfs may be bastards, yet not all bastards need be dwarfs.", speaker: "Tyrion Lannister", wrong: ["Varys", "Bronn", "Jorah Mormont"], b: 1, hint: "A small man's wry parting lesson to a bastard heading for the Wall.", context: "Tyrion's farewell wisdom to Jon Snow, comparing the two kinds of outsider they both are." },
  { d: 3, fmt: "book", q: "So the wolfling is leaving his den to play among the lions.", speaker: "Tywin Lannister", wrong: ["Kevan Lannister", "Jaime Lannister", "Cersei Lannister"], b: 1, hint: "A father's cold satisfaction on hearing a young northern king means to march south.", context: "Tywin's private remark on learning that Robb Stark intends to bring the war to the Lannisters." },
  { d: 3, fmt: "book", q: "When soldiers lack discipline, the fault lies with their lord commander.", speaker: "Tywin Lannister", wrong: ["Kevan Lannister", "Roose Bolton", "Jaime Lannister"], b: 1, hint: "A father's lesson about command, used to excuse his own men's crimes.", context: "Tywin's justification to Tyrion at Harrenhal for the outrages committed by his soldiers." },
  { d: 1, fmt: "book", q: "You are done with whores. The next one I find in your bed, I'll hang.", speaker: "Tywin Lannister", wrong: ["Kevan Lannister", "Cersei Lannister", "Jaime Lannister"], b: 3, hint: "A father's icy ultimatum to his least-favorite son about the woman warming his bed.", context: "Tywin's threat to Tyrion over Shae, delivered with his usual lack of warmth." },
  { d: 3, fmt: "book", q: "When a dog goes bad, the fault lies with his master.", speaker: "Kevan Lannister", wrong: ["Tywin Lannister", "Jaime Lannister", "Grand Maester Pycelle"], b: 4, hint: "An uncle's pointed rebuke about a savage killer once kept on House Lannister's leash.", context: "Kevan's remark to Cersei about the Hound — and about who really shaped him." },
  { d: 3, fmt: "book", q: "Dead men don't shit.", speaker: "Kevan Lannister", wrong: ["Grand Maester Pycelle", "Tywin Lannister", "Qyburn"], b: 5, hint: "An old lord's crude, private suspicion about a hulking new addition to the Kingsguard.", context: "Kevan's blunt realization, in the novel's epilogue, about what 'Ser Robert Strong' really is." },
  { d: 3, fmt: "book", q: "Women were always the cruelest where other women were concerned.", speaker: "Cersei Lannister", wrong: ["Margaery Tyrell", "Olenna Tyrell", "Catelyn Stark"], b: 5, hint: "A queen's cynical private verdict on her own sex.", context: "One of Cersei's bitter observations about the women around her, from her own point-of-view chapters." },
  { d: 3, fmt: "book", q: "This is what comes of letting fools and cowards rule themselves. Next time, I will choose their master for them.", speaker: "Cersei Lannister", wrong: ["Tywin Lannister", "Tommen Baratheon", "Kevan Lannister"], b: 4, hint: "A regent's chilly conclusion after the smallfolk of her own city turn unruly.", context: "Cersei's private response to unrest in King's Landing, revealing exactly how she plans to handle it." },
  { d: 3, fmt: "book", q: "The singers make much of kings who valiantly die in battle, but your life is worth more than a sword.", speaker: "Catelyn Stark", wrong: ["Brynden Tully", "Eddard Stark", "Sansa Stark"], b: 3, hint: "A mother's plea to her son-king, about valuing survival over glory.", context: "Catelyn's warning to Robb, urging him not to risk himself needlessly in battle." },
  { d: 1, fmt: "book", q: "You each name yourself king, yet the kingdom bleeds and no one lifts a sword to defend it but my son.", speaker: "Catelyn Stark", wrong: ["Brynden Tully", "Sansa Stark", "Robb Stark"], b: 2, hint: "A grieving mother's rebuke to two rival claimants meeting under a peace banner.", context: "Catelyn's words to Renly and Stannis Baratheon at their tense parley outside Storm's End." },
  { d: 3, fmt: "book", q: "The dungeons are windowless. One hour is much like another down there, and for me, all hours are midnight.", speaker: "Catelyn Stark", wrong: ["Sansa Stark", "Lysa Arryn", "Brienne of Tarth"], b: 2, hint: "A grieving mother's grim private thought, keeping vigil over a captive she can't bring herself to kill.", context: "Catelyn's reflection while visiting Jaime Lannister in his cell at Riverrun." },
  { d: 3, fmt: "book", q: "Show me the path I must walk and do not let me stumble in the dark places that lie ahead.", speaker: "Catelyn Stark", wrong: ["Sansa Stark", "Lysa Arryn", "Brienne of Tarth"], b: 2, hint: "A mother's private prayer, said to gods she's never been certain are listening.", context: "Catelyn's prayer in a godswood, seeking guidance as the war around her family worsens." },
  { d: 1, fmt: "book", q: "Poison is a coward's weapon.", speaker: "Eddard Stark", wrong: ["Robert Baratheon", "Varys", "Jorah Mormont"], b: 1, hint: "A blunt northern lord's objection to killing from the shadows.", context: "Ned's refusal to countenance a plan to have Daenerys Targaryen assassinated by poison." },
  { d: 3, fmt: "book", q: "Lord Umber, this one was only the watcher. Hang him last, so he may watch the others die.", speaker: "Robb Stark", wrong: ["Eddard Stark", "Jon Snow", "Brynden Tully"], b: 3, hint: "A young king in the North, handing down grim justice to a captured spy.", context: "Robb's sentence for one of the ironborn caught after the fall of Winterfell." },
  { d: 1, fmt: "book", q: "My skin has turned to porcelain, to ivory, to steel.", speaker: "Sansa Stark", wrong: ["Cersei Lannister", "Catelyn Stark", "Margaery Tyrell"], b: 3, hint: "A young bride's private chant, said to herself in a godswood on the morning of a marriage she never wanted.", context: "Sansa's silent mantra as she tries to steel her nerve before her wedding to Tyrion Lannister." },
  { d: 1, fmt: "book", q: "He is no true knight, but he saved me all the same.", speaker: "Sansa Stark", wrong: ["Arya Stark", "Catelyn Stark", "Brienne of Tarth"], b: 2, hint: "A frightened young lady's private verdict on a frightening man who pulled her from a mob.", context: "Sansa's thought about Sandor Clegane, after he rescues her during a riot in King's Landing." },
  { d: 3, fmt: "book", q: "Be brave. Be brave, like a lady in a song.", speaker: "Sansa Stark", wrong: ["Arya Stark", "Margaery Tyrell", "Catelyn Stark"], b: 3, hint: "A young bride coaching herself through fear the only way she knows how.", context: "Sansa's private pep talk to herself, bracing for another ordeal at court." },
  { d: 1, fmt: "book", q: "I am a wolf, and will not be afraid.", speaker: "Arya Stark", wrong: ["Sansa Stark", "Osha", "Brienne of Tarth"], b: 4, hint: "A girl far from home, steadying her own nerve before slipping into the dark.", context: "Arya's private reassurance to herself before descending into danger alone, on the streets of Braavos." },
  { d: 3, fmt: "book", q: "Your wolves have more wit than your maester. They know truths the grey man has forgotten.", speaker: "Osha", wrong: ["Jojen Reed", "Meera Reed", "Maester Luwin"], b: 2, hint: "A wildling woman's blunt praise for a boy's direwolf, at the expense of his tutor.", context: "Osha's remark to Bran at Winterfell, trusting Summer's instincts over Maester Luwin's book-learning." },
  { d: 3, fmt: "book", q: "Peace. Land. Victory. I'll give you Sea Dragon Point and the Stony Shore, black earth and tall trees and stones enough for every younger son to build a hall.", speaker: "Asha Greyjoy", wrong: ["Theon Greyjoy", "Balon Greyjoy", "Victarion Greyjoy"], b: 4, hint: "An ironborn captain's own bid for the driftwood crown, promising plunder without more war.", context: "Asha's speech to the assembled captains and kings at the kingsmoot on Old Wyk." },
  { d: 1, fmt: "book", q: "Why is it always the innocents who suffer most, when you high lords play your game of thrones?", speaker: "Varys", wrong: ["Petyr Baelish", "Tyrion Lannister", "Tywin Lannister"], b: 1, hint: "A eunuch's pointed complaint about who really pays for the powerful's ambitions.", context: "Varys speaking to Ned Stark in the dungeons, about the harm done by the war his investigation has stirred up." },
  { d: 1, fmt: "book", q: "The Red Keep shelters two sorts of people, Lord Eddard. Those who are loyal to the realm, and those who are loyal only to themselves.", speaker: "Varys", wrong: ["Petyr Baelish", "Tywin Lannister", "Tyrion Lannister"], b: 1, hint: "A spymaster sorting the court into two simple camps for a newly arrived Hand.", context: "Varys's assessment of King's Landing, offered to Ned Stark not long after his arrival at court." },
  { d: 3, fmt: "book", q: "So those are your gifts from me, my sweet Sansa: Harry, the Eyrie, and Winterfell.", speaker: "Petyr Baelish", wrong: ["Robin Arryn", "Lysa Arryn", "Cersei Lannister"], b: 4, hint: "A schemer laying out a young woman's future inheritance, piece by piece, like presents.", context: "Littlefinger explaining his long game to Sansa, hidden away in the Vale under a false name." },
  { d: 3, fmt: "book", q: "If you know who's going to win the second match, speak up now before Lord Renly plucks me clean.", speaker: "Petyr Baelish", wrong: ["Renly Baratheon", "Varys", "Robert Baratheon"], b: 1, hint: "A gambling lord's wry aside about wagers already lost at a tournament.", context: "Littlefinger's joke to Ned Stark at the Hand's tourney, about his own bad bets." },
  { d: 1, fmt: "book", q: "The septons preach about the seven hells. What do they know? Only a man who's been burned knows what hell is truly like.", speaker: "Sandor Clegane", wrong: ["Gregor Clegane", "Beric Dondarrion", "Jaime Lannister"], b: 1, hint: "A scarred fighter's blunt rejection of a priest's idea of suffering.", context: "The Hound's grim aside to Sansa about his own burned face, and what he thinks 'hell' really means." },
  { d: 1, fmt: "book", q: "You're like one of those birds from the Summer Isles, aren't you? A pretty little talking bird, repeating all the pretty little words they taught you to recite.", speaker: "Sandor Clegane", wrong: ["Joffrey Baratheon", "Petyr Baelish", "Tyrion Lannister"], b: 1, hint: "A blunt-spoken guard, mocking a young lady's practiced courtesies.", context: "The Hound's cutting remark to Sansa, needling her for hiding behind rehearsed politeness." },
  { d: 3, fmt: "book", q: "Peace is sweet, my lady, but on what terms? It is no good hammering your sword into a plowshare if you must forge it again on the morrow.", speaker: "Brynden Tully", wrong: ["Catelyn Stark", "Edmure Tully", "Robb Stark"], b: 2, hint: "A grizzled uncle's skepticism about any truce that won't actually hold.", context: "The Blackfish's blunt counsel to his niece Catelyn about the dangers of a hasty peace." },
  { d: 3, fmt: "book", q: "I am a bloodthirsty man, you see. And it is me you must contend with now, not my patient, prudent, and gouty brother.", speaker: "Oberyn Martell", wrong: ["Doran Martell", "Tyrion Lannister", "Jaime Lannister"], b: 3, hint: "A vengeful Dornish prince warning a Lannister prisoner that he isn't the reasonable brother.", context: "Oberyn's words to Tyrion in his cell, contrasting himself with Prince Doran before the two strike a bargain." },
  { d: 1, fmt: "book", q: "You are my queen, my sword is yours, but do not ask me to stand aside as you climb on Drogo's pyre. I will not watch you burn.", speaker: "Jorah Mormont", wrong: ["Barristan Selmy", "Daario Naharis", "Grey Worm"], b: 1, hint: "An exiled knight's desperate plea to the young queen he's sworn to serve.", context: "Jorah begging Daenerys not to join Khal Drogo's funeral pyre after his death." },
  { d: 1, fmt: "book", q: "I heard a Lannister always pays his debts. Oh, every penny ... but never a groat more.", speaker: "Jorah Mormont", wrong: ["Barristan Selmy", "Daario Naharis", "Tyrion Lannister"], b: 5, hint: "An exiled knight's dry needling of the dwarf he's just captured.", context: "Jorah's sardonic banter with Tyrion, taking him prisoner on the road to Meereen." },
  { d: 3, fmt: "book", q: "Tell Khal Drogo that he has given me the wind.", speaker: "Daenerys Targaryen", wrong: ["Irri", "Doreah", "Missandei"], b: 1, hint: "A young khaleesi's delighted message, sent back after her first ride on a new gift.", context: "Dany's words after riding her silver horse, a gift from Khal Drogo, for the first time." },
  { d: 3, fmt: "book", q: "Soon comes the cold, and the night that never ends.", speaker: "Melisandre", wrong: ["Davos Seaworth", "Stannis Baratheon", "Selyse Baratheon"], b: 3, hint: "A red priestess's grim prophecy about the enemy her god was made to fight.", context: "One of Melisandre's visions of the long night to come, shared with her king's small, doubting court." },
  { d: 3, fmt: "book", q: "It is night in your Seven Kingdoms now, but soon the sun will rise again.", speaker: "Melisandre", wrong: ["Davos Seaworth", "Stannis Baratheon", "Selyse Baratheon"], b: 3, hint: "A red priestess's promise, framed as prophecy, to a court that isn't sure it believes her.", context: "Melisandre's assurance about the war to come, delivered with her usual certainty." },
  { d: 1, fmt: "book", q: "I held a castle on the Marches once, and there was a woman I was pledged to marry, but I could not find that castle today, nor tell you the color of that woman's hair.", speaker: "Beric Dondarrion", wrong: ["Thoros of Myr", "Sandor Clegane", "Edmure Tully"], b: 3, hint: "A many-times-dead knight's quiet grief over everything his resurrections have cost him.", context: "Beric explaining to Arya how each time he's brought back, he loses a little more of who he was." },
  { d: 3, fmt: "book", q: "Eagles have sharper eyes than men. We are seen. So now we run.", speaker: "Qhorin Halfhand", wrong: ["Jon Snow", "Mance Rayder", "Jeor Mormont"], b: 2, hint: "A grim ranger's terse call to abandon a scouting mission gone wrong.", context: "Qhorin's order to his small party beyond the Wall, after realizing Mance Rayder's forces have spotted them." },
  { d: 3, fmt: "book", q: "They name themselves the free folk, and each one thinks himself as good as a king and wiser than a maester.", speaker: "Qhorin Halfhand", wrong: ["Jeor Mormont", "Mance Rayder", "Craster"], b: 2, hint: "A hardened ranger's assessment of the wildlings' one great weakness.", context: "Qhorin's explanation to Jon Snow of why the free folk, for all their courage, struggle to fight as one." },
  { d: 3, fmt: "book", q: "A man will tell you poison is dishonorable, but a woman's honor is different. The Mother shaped us to protect our children, and our only dishonor is in failure.", speaker: "Lysa Arryn", wrong: ["Catelyn Stark", "Cersei Lannister", "Sansa Stark"], b: 3, hint: "A frightened, possessive mother's justification for a murder committed years before.", context: "Lysa's confession to Sansa in the Eyrie, defending her poisoning of Jon Arryn as an act of protection." },
  { d: 3, fmt: "book", q: "The Eyrie is impregnable. The Imp is trying to frighten us, sweet baby. The Lannisters are all liars. No one will hurt my sweet boy.", speaker: "Lysa Arryn", wrong: ["Catelyn Stark", "Robin Arryn", "Cersei Lannister"], b: 1, hint: "An anxious mother's frantic reassurance to her own frightened son.", context: "Lysa soothing Robin at the Eyrie, dismissing Tyrion Lannister's warnings about the coming war." },
  { d: 1, fmt: "book", q: "I have taught my Margaery what comely is worth, I hope. Less than a mummer's fart.", speaker: "Olenna Tyrell", wrong: ["Cersei Lannister", "Mace Tyrell", "Loras Tyrell"], b: 3, hint: "A grandmother's blunt lesson about beauty's real value in the game of thrones.", context: "Olenna's dismissive remark to Sansa about the lessons she's made sure her granddaughter has learned." },
  { d: 3, fmt: "book", q: "The trees watch over us. In the forest, they see all ... but there are no trees here. Only water, Sam. Only water.", speaker: "Gilly", wrong: ["Ygritte", "Osha", "Meera Reed"], b: 3, hint: "A wildling girl's unease, far from the godswoods she was raised to trust.", context: "Gilly's worried remark to Samwell Tarly, no longer under the watchful eyes of the old gods." },
  { d: 1, fmt: "book", q: "I've never had a crown on my head or sat my arse on a bloody throne, if that's what you're asking.", speaker: "Mance Rayder", wrong: ["Balon Greyjoy", "Robb Stark", "Renly Baratheon"], b: 2, hint: "A king who isn't much for the trappings of kingship, correcting an assumption.", context: "Mance Rayder's wry deflection when someone treats his title as if it came with a throne room." },
  { d: 3, fmt: "book", q: "Someone told. Someone always tells.", speaker: "Areo Hotah", wrong: ["Doran Martell", "Oberyn Martell", "Arys Oakheart"], b: 4, hint: "A stone-faced guard captain's flat, weary explanation for how a secret plot unraveled.", context: "Hotah's blunt answer when Arianne Martell asks how her scheme to crown Myrcella was discovered." },
  { d: 3, fmt: "book", q: "It is the Drowned God we must please. Have you been drowned, Gormond Goodbrother?", speaker: "Aeron Greyjoy", wrong: ["Victarion Greyjoy", "Balon Greyjoy", "Euron Greyjoy"], b: 4, hint: "A priest of the drowned faith, testing a captain's devotion before a gathering of ironborn.", context: "Aeron Damphair questioning one of the assembled captains ahead of the kingsmoot on Old Wyk." },
  { d: 1, fmt: "book", q: "This is what I was made for. The dance, the sweet steel song, a sword in my hand and a foe before me.", speaker: "Barristan Selmy", wrong: ["Jorah Mormont", "Jaime Lannister", "Daario Naharis"], b: 5, hint: "An aging knight, finally back in a fight worthy of his old reputation.", context: "Barristan's private thought as he takes up arms again in Meereen, feeling like himself for the first time in years." },

  // ================= BOOK — HARD =================
  { d: 3, fmt: "book", q: "Give him fifteen years, he'll be fatter than his father.", speaker: "Cersei Lannister", wrong: ["Jaime Lannister", "Tywin Lannister", "Kevan Lannister"], b: 1, hint: "A cutting remark about a husband, from a wife who has stopped pretending to love him.", context: "Cersei's private aside about Robert Baratheon's decline, before his death sets the story in motion." },
  { d: 1, fmt: "book", q: "A dragon is no slave.", speaker: "Daenerys Targaryen", wrong: ["Missandei", "Grey Worm", "Mirri Maz Duur"], b: 1, hint: "A young queen's final rebuke to the man who sold her a horse — and much more.", context: "Daenerys's answer to Kraznys mo Nakloz's slaver's Valyrian, spoken back in fluent, furious High Valyrian." },
  { d: 3, fmt: "book", q: "Nothing burns like the cold.", speaker: "Melisandre", wrong: ["Davos Seaworth", "Stannis Baratheon", "Selyse Baratheon"], b: 5, hint: "A red priestess's saying about the enemy her god was made to fight.", context: "Melisandre's grim reflection, from her own chapters late in the story, on the true nature of the enemy beyond the Wall." },

  // ================= BOOK — HARD (batch 2) =================
  { d: 3, fmt: "book", q: "Serve. Protect. Obey. Simple vows for simple men.", speaker: "Areo Hotah", wrong: ["Arys Oakheart", "Barristan Selmy", "Victarion Greyjoy"], b: 4, hint: "A Norvoshi axeman's private creed, said of the only code he's ever needed.", context: "Areo Hotah's own summary of his life's purpose as captain of the Sunspear guard, thought to himself rather than spoken aloud." },
  { d: 3, fmt: "book", q: "What you meant does not matter, little princess. Only what you did.", speaker: "Areo Hotah", wrong: ["Arys Oakheart", "Barristan Selmy", "Doran Martell"], b: 4, hint: "A guard captain's blunt reply to a princess's excuse.", context: "Hotah's response to Arianne Martell after her scheme to crown Myrcella goes wrong, refusing to let good intentions excuse the outcome." },
  { d: 3, fmt: "book", q: "You drink a deal of wine for such a little man.", speaker: "Illyrio Mopatis", wrong: ["Varys", "Xaro Xhoan Daxos", "Kraznys mo Nakloz"], b: 5, hint: "A fat magister needling his exiled, wine-soaked houseguest in Pentos.", context: "Illyrio's remark to Tyrion, sharing wine in his cellar after Tyrion's flight from Westeros." },
  { d: 3, fmt: "book", q: "You cannot hope to rule. You are a woman.", speaker: "Victarion Greyjoy", wrong: ["Euron Greyjoy", "Aeron Greyjoy", "Balon Greyjoy"], b: 4, hint: "One captain's blunt objection to his niece's claim at a gathering of the isles.", context: "Victarion's dismissal of Asha's bid for the driftwood crown at the kingsmoot on Old Wyk." },
  { d: 3, fmt: "book", q: "Is that why I always lose the pissing contests?", speaker: "Asha Greyjoy", wrong: ["Victarion Greyjoy", "Euron Greyjoy", "Aeron Greyjoy"], b: 4, hint: "A niece's dry retort to an uncle who doubts a woman can rule.", context: "Asha's answer to Victarion at the kingsmoot, unbothered by his objection to her claim." },
  { d: 3, fmt: "book", q: "A little brother may live to be a hundred, but he will always be a little brother.", speaker: "Asha Greyjoy", wrong: ["Sansa Stark", "Brienne of Tarth", "Maege Mormont"], b: 5, hint: "A sister's private thought about a brother she hasn't seen grow up.", context: "Asha's reflection on Theon, recalling him as a boy still in awe of his older brothers, from her own point-of-view chapters." },
  { d: 3, fmt: "book", q: "Aeron, I am the godliest man ever to raise sail! You serve one god, Damphair, but I have served ten thousand.", speaker: "Euron Greyjoy", wrong: ["Victarion Greyjoy", "Balon Greyjoy", "Theon Greyjoy"], b: 4, hint: "A returned, godless brother mocking a priest's devotion to the Drowned God.", context: "Euron's taunt to his brother Aeron, boasting of the many gods and ports he's known in his years of reaving." },
  { d: 3, fmt: "book", q: "Hear me, Daenerys Targaryen. The glass candles are burning. Soon comes the pale mare, and after her the others. Kraken and dark flame, lion and griffin, the sun's son and the mummer's dragon. Trust none of them. Remember the Undying. Beware the perfumed seneschal.", speaker: "Quaithe", wrong: ["Melisandre", "Mirri Maz Duur", "Missandei"], b: 5, hint: "A masked shadowbinder's warning, delivered entirely in riddles.", context: "Quaithe's cryptic prophecy to Daenerys in Meereen, naming dangers still to come by animal and title rather than name." },
  { d: 3, fmt: "book", q: "Man wants to bed a woman, seems like he ought to take her to wife. That's what I do.", speaker: "Craster", wrong: ["Mance Rayder", "Rattleshirt", "Qhorin Halfhand"], b: 2, hint: "A wildling patriarch's self-justifying idea of marriage, said to a bastard he's just met.", context: "Craster's blunt explanation of his own household to Jon Snow, at his keep beyond the Wall." },
  { d: 3, fmt: "book", q: "There have always been men who found it easier to speak vows than to keep them.", speaker: "Arys Oakheart", wrong: ["Jaime Lannister", "Barristan Selmy", "Boros Blount"], b: 4, hint: "A white-cloaked knight's excuse for himself, spoken to the Dornish princess he loves.", context: "Arys's answer to Arianne Martell in Sunspear, weighing his Kingsguard vows against his feelings for her." },
  { d: 3, fmt: "book", q: "You will pardon me if I do not rise. Our march was wearisome, and my toes are prone to blisters. It is a curse.", speaker: "Harry Strickland", wrong: ["Euron Greyjoy", "Illyrio Mopatis", "Victarion Greyjoy"], b: 5, hint: "A sellsword captain's unglamorous complaint, made upon meeting an exiled lord.", context: "Harry Strickland, captain-general of the Golden Company, greeting Jon Connington with more talk of his feet than of war." },
  { d: 3, fmt: "book", q: "I am an old man, an old knight, and I have seen more battles than most of you have years.", speaker: "Barristan Selmy", wrong: ["Jorah Mormont", "Illyrio Mopatis", "Victarion Greyjoy"], b: 5, hint: "An old knight reminding younger men in Meereen exactly who he is.", context: "Barristan's words during his command of Meereen's defenders, from his own point-of-view chapters late in the story." },
  { d: 3, fmt: "book", q: "What you propose is nothing less than treason.", speaker: "Bowen Marsh", wrong: ["Alliser Thorne", "Janos Slynt", "Maester Aemon"], b: 5, hint: "The Night's Watch's Lord Steward, aghast at his new commander's plan for the wildlings.", context: "Bowen Marsh's objection to Jon Snow's decision to let the free folk pass through the Wall." },
  { d: 3, fmt: "book", q: "There will be pain.", speaker: "Qyburn", wrong: ["Grand Maester Pycelle", "Maester Luwin", "Maester Cressen"], b: 3, hint: "A disgraced maester's calm warning, just before he starts to work.", context: "Qyburn preparing to tend Jaime's wound after the loss of his hand." },
  { d: 3, fmt: "book", q: "The Others never come when the sun is up.", speaker: "Mance Rayder", wrong: ["Tormund Giantsbane", "Rattleshirt", "Craster"], b: 3, hint: "The King-Beyond-the-Wall explaining an old truth about the enemy to a captive crow.", context: "Mance's remark to Jon Snow about the enemy beyond the Wall and when it dares to strike." },
  { d: 3, fmt: "book", q: "She-bears, aye. We have needed to be. In olden days the ironmen would come raiding in their longboats, or wildlings from the Frozen Shore. The men would be off fishing, like as not. The wives they left behind had to defend themselves and their children, or else be carried off.", speaker: "Maege Mormont", wrong: ["Lyanna Mormont", "Brienne of Tarth", "Asha Greyjoy"], b: 3, hint: "A northern lady explaining why the women of her island fight as fiercely as the men.", context: "Maege Mormont's answer to Catelyn about why Bear Island's women are raised as warriors." },
  // ---- added Aug 2026: lines with a voice, not statements of position ----
  { d: 3, fmt: "show", q: "I've been a soldier. I know what soldiers do. They rape. They kill. They burn.", speaker: "Sandor Clegane", wrong: ["Bronn", "Jorah Mormont", "Beric Dondarrion"], s: 4, hint: "Said flatly, by a man who is not making an accusation but a description.", context: "The Hound has no illusions about the trade he was raised into, and none about himself." },
  { d: 3, fmt: "show", q: "You're going to die tomorrow. Open your eyes and look at me. See? Nothing.", speaker: "Melisandre", wrong: ["Ellaria Sand", "Olenna Tyrell", "Arya Stark"], s: 5, hint: "A promise dressed up as a comfort.", context: "Spoken with complete calm, which is what makes it land." },
  { d: 3, fmt: "show", q: "If I want pretty I'll get a whore. If I want a queen I'll buy one.", speaker: "Randyll Tarly", wrong: ["Tywin Lannister", "Roose Bolton", "Walder Frey"], s: 7, hint: "A hard lord explaining his own price to a queen who is offering one.", context: "Blunt to the point of self-harm, which is the whole of him." },
  { d: 3, fmt: "show", q: "The powerful have always preyed on the powerless. That's how they became powerful in the first place.", speaker: "Petyr Baelish", wrong: ["Varys", "Tywin Lannister", "Olenna Tyrell"], s: 5, hint: "An observation, from someone who has been on both ends of it.", context: "The plainest statement of his worldview, and closer to an autobiography than he means it to be." },
  { d: 3, fmt: "show", q: "I did what I did for the good of the realm.", speaker: "Varys", wrong: ["Petyr Baelish", "Grand Maester Pycelle", "Qyburn"], s: 8, hint: "A defence offered by a man who has said it in four reigns.", context: "The one thing he has ever been consistent about, and the one thing nobody in power ever believes." },
  { d: 3, fmt: "show", q: "Everything before the word 'but' is horse shit.", speaker: "Tywin Lannister", wrong: ["Bronn", "Sandor Clegane", "Davos Seaworth"], s: 5, hint: "A lesson in listening, from a man who did a great deal of it.", context: "Passed to a grandson who was never going to be able to use it." },
  { d: 3, fmt: "show", q: "Nothing's worth anything to dead men.", speaker: "Ygritte", wrong: ["Osha", "Tormund Giantsbane", "Gilly"], s: 3, hint: "A free folk answer to a kneeler's talk of honour.", context: "The whole of the wildling argument with the south, in six words." },
  { d: 3, fmt: "show", q: "You've been a good friend to my family. And you're the best fighter I've ever seen. Would you be my Queensguard?", speaker: "Daenerys Targaryen", wrong: ["Sansa Stark", "Cersei Lannister", "Margaery Tyrell"], s: 7, hint: "An offer made to a knight who has spent the whole story being laughed at.", context: "One of the few unambiguously kind things anybody does for Brienne of Tarth." },
  { d: 3, fmt: "book", q: "A bruise is a lesson, and each lesson makes us better.", speaker: "Arya Stark", wrong: ["Brienne of Tarth", "Jon Snow", "Robb Stark"], b: 1, hint: "Repeated to herself, in a voice she is copying from somebody else.", context: "Syrio Forel's teaching, kept and recited by a girl who has nothing else of him left." },
  { d: 3, fmt: "book", q: "Never forget what you are. The rest of the world will not. Wear it like armour, and it can never be used to hurt you.", speaker: "Tyrion Lannister", wrong: ["Varys", "Petyr Baelish", "Jaime Lannister"], b: 1, hint: "Advice on being despised, from an expert.", context: "Said to a bastard boy on the kingsroad by a dwarf who has had thirty years to work it out." },
  { d: 3, fmt: "book", q: "Half the world is women. It is the half that makes the other half.", speaker: "Olenna Tyrell", wrong: ["Cersei Lannister", "Catelyn Stark", "Lysa Arryn"], b: 3, hint: "Delivered dryly, by somebody who has outlived every man who disagreed.", context: "The Queen of Thorns has spent seventy years watching men run things badly and saying so." },
  { d: 3, fmt: "show", q: "There's no cure for being a c***. But the boy is a boy.", speaker: "Bronn", wrong: ["Sandor Clegane", "Tormund Giantsbane", "Davos Seaworth"], s: 4, hint: "A sellsword's assessment of a king, offered without being asked.", context: "Bronn's entire method of political analysis, and often the most accurate one in the room." },
];
